// src/components/Ganancias/ComparativaMensual.js
import React from 'react';
import { Box, Typography } from '@mui/material';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import SentimentDissatisfiedIcon from '@mui/icons-material/SentimentDissatisfied';

const ComparativaMensual = ({ gananciasPorMes = [], obtenerNombreMes }) => {
    if (gananciasPorMes.length < 2) return null;

    const mesActualData = gananciasPorMes[0];
    const mesAnteriorData = gananciasPorMes[1];

    const diferencia = mesActualData.total - mesAnteriorData.total;
    const porcentajeCambio = mesAnteriorData.total > 0
        ? ((mesActualData.total - mesAnteriorData.total) / mesAnteriorData.total) * 100
        : 100;

    const esPositivo = diferencia >= 0;

    // Calcular si está mejor o peor que el promedio de los últimos 3 meses
    const ultimos3Meses = gananciasPorMes.slice(0, 3);
    const promedio3Meses = ultimos3Meses.length > 0
        ? ultimos3Meses.reduce((sum, mes) => sum + mes.total, 0) / ultimos3Meses.length
        : 0;

    const vsPromedio3Meses = promedio3Meses > 0
        ? ((mesActualData.total - promedio3Meses) / promedio3Meses) * 100
        : 0;

    return (
        <Box sx={{
            mt: 3,
            p: 2,
            borderRadius: 2,
            boxShadow: 2,
            backgroundColor: esPositivo ? '#f0f9ff' : '#fff5f5',
            border: `2px solid ${esPositivo ? '#a5d8ff' : '#ffc9c9'}`
        }}>
            {/* Encabezado */}
            <Box sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                mb: 2
            }}>
                <Typography variant="h6" sx={{
                    color: esPositivo ? '#1971c2' : '#c92a2a',
                    display: 'flex',
                    alignItems: 'center',
                    gap: 1
                }}>
                    {esPositivo ? <TrendingUpIcon /> : <TrendingDownIcon />}
                    Comparativa Mensual
                </Typography>

                <Box sx={{
                    px: 2,
                    py: 0.5,
                    borderRadius: 4,
                    backgroundColor: esPositivo ? '#d3f9d8' : '#ffe3e3'
                }}>
                    <Typography variant="subtitle2" fontWeight="bold" color={esPositivo ? '#2b8a3e' : '#c92a2a'}>
                        {esPositivo ? '+' : ''}{porcentajeCambio.toFixed(1)}%
                    </Typography>
                </Box>
            </Box>

            {/* Comparativa principal */}
            <Box sx={{
                display: 'grid',
                gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr 1fr' },
                gap: 2,
                mb: 3
            }}>
                {/* Mes Actual */}
                <Box sx={{
                    p: 2,
                    borderRadius: 2,
                    backgroundColor: 'white',
                    textAlign: 'center',
                    boxShadow: 1,
                    border: '2px solid #4dabf7'
                }}>
                    <Typography variant="subtitle2" color="#1971c2" fontWeight="bold">
                        {obtenerNombreMes(mesActualData.mes)} {mesActualData.anio}
                    </Typography>
                    <Typography variant="h4" fontWeight="bold" color="#1971c2" sx={{ mt: 1 }}>
                        ${mesActualData.total.toLocaleString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        {mesActualData.diasTrabajados.size} días trabajados
                    </Typography>
                </Box>

                {/* Diferencia */}
                <Box sx={{
                    p: 2,
                    borderRadius: 2,
                    backgroundColor: esPositivo ? '#d3f9d8' : '#ffe3e3',
                    textAlign: 'center',
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center'
                }}>
                    <Typography variant="subtitle2" fontWeight="bold" color={esPositivo ? '#2b8a3e' : '#c92a2a'}>
                        {esPositivo ? 'INCREMENTO' : 'DECREMENTO'}
                    </Typography>
                    <Typography variant="h5" fontWeight="bold" color={esPositivo ? '#2b8a3e' : '#c92a2a'} sx={{ my: 1 }}>
                        {esPositivo ? '↑' : '↓'} ${Math.abs(diferencia).toLocaleString()}
                    </Typography>
                    <Typography variant="body2" color={esPositivo ? '#2b8a3e' : '#c92a2a'}>
                        vs mes anterior
                    </Typography>
                </Box>

                {/* Mes Anterior */}
                <Box sx={{
                    p: 2,
                    borderRadius: 2,
                    backgroundColor: 'white',
                    textAlign: 'center',
                    boxShadow: 1,
                    border: '2px solid #adb5bd'
                }}>
                    <Typography variant="subtitle2" color="#868e96" fontWeight="bold">
                        {obtenerNombreMes(mesAnteriorData.mes)} {mesAnteriorData.anio}
                    </Typography>
                    <Typography variant="h4" fontWeight="bold" color="#868e96" sx={{ mt: 1 }}>
                        ${mesAnteriorData.total.toLocaleString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        {mesAnteriorData.diasTrabajados.size} días trabajados
                    </Typography>
                </Box>
            </Box>

            {/* Estadísticas adicionales */}
            <Box sx={{
                display: 'grid',
                gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
                gap: 2,
                mt: 2
            }}>
                {/* Comparativa con promedio de 3 meses */}
                <Box sx={{
                    p: 1.5,
                    borderRadius: 1,
                    backgroundColor: 'white',
                    boxShadow: 1
                }}>
                    <Typography variant="body2" color="text.secondary">
                        vs Promedio últimos 3 meses:
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mt: 0.5 }}>
                        <Typography variant="h6" fontWeight="bold" color={vsPromedio3Meses >= 0 ? 'green' : 'red'}>
                            {vsPromedio3Meses >= 0 ? '+' : ''}{vsPromedio3Meses.toFixed(1)}%
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                            ${promedio3Meses.toLocaleString('es-AR', {
                                minimumFractionDigits: 0,
                                maximumFractionDigits: 0
                            })}
                        </Typography>
                    </Box>
                </Box>

                {/* Rendimiento por día */}
                <Box sx={{
                    p: 1.5,
                    borderRadius: 1,
                    backgroundColor: 'white',
                    boxShadow: 1
                }}>
                    <Typography variant="body2" color="text.secondary">
                        Rendimiento por día:
                    </Typography>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mt: 0.5 }}>
                        <Typography variant="h6" fontWeight="bold">
                            ${(mesActualData.total / mesActualData.diasTrabajados.size).toLocaleString('es-AR', {
                                minimumFractionDigits: 0,
                                maximumFractionDigits: 0
                            })}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                            por día
                        </Typography>
                    </Box>
                </Box>
            </Box>

            {/* Mensaje motivacional */}
            <Box sx={{
                mt: 2,
                p: 2,
                borderRadius: 1,
                backgroundColor: esPositivo ? '#d3f9d8' : '#fff3bf',
                border: `1px solid ${esPositivo ? '#b2f2bb' : '#ffd8a8'}`
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                    {esPositivo ? <EmojiEventsIcon color="success" /> : <SentimentDissatisfiedIcon color="warning" />}
                    <Typography variant="subtitle2" fontWeight="bold">
                        {esPositivo ? '¡Excelente trabajo!' : '¡Ánimo, puedes mejorar!'}
                    </Typography>
                </Box>
                <Typography variant="body2">
                    {esPositivo
                        ? `Estás ganando un ${porcentajeCambio.toFixed(1)}% más que el mes anterior. 
               ¡Sigue así y terminarás el mes con excelentes resultados! 💪`
                        : `Estás ${Math.abs(porcentajeCambio).toFixed(1)}% por debajo del mes anterior. 
               Intenta analizar qué funcionó mejor ese mes y aplica esas estrategias ahora.`
                    }
                </Typography>
            </Box>
        </Box>
    );
};

export default ComparativaMensual;