// src/components/Ganancias/EstadisticasZona.js
import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
    Box,
    Typography,
    Paper,
    Chip,
    Tooltip,
    ToggleButton,
    ToggleButtonGroup
} from '@mui/material';
import {
    BarChart as BarChartIcon,
    PieChart as PieChartIcon,
    LocationOn as LocationIcon,
    Star as StarIcon
} from '@mui/icons-material';
import { Chart, registerables } from 'chart.js';

// Registrar todos los componentes de Chart.js
Chart.register(...registerables);

const EstadisticasZona = ({ gananciasPorDia = [] }) => {
    const [viewType, setViewType] = useState('pie');
    const [sortBy, setSortBy] = useState('total');

    // Referencias para los canvas de gráficos
    const pieChartRef = useRef(null);
    const barChartRef = useRef(null);
    const pieChartInstance = useRef(null);
    const barChartInstance = useRef(null);

    // Calcular estadísticas por zona
    const estadisticas = useMemo(() => {
        const zonas = {};

        gananciasPorDia.forEach(g => {
            const zona = g.zona || "Sin zona especificada";
            const fecha = new Date(g.fechaGanancia).toLocaleDateString();

            if (!zonas[zona]) {
                zonas[zona] = {
                    total: 0,
                    count: 0,
                    dias: new Set(),
                };
            }

            zonas[zona].total += g.total;
            zonas[zona].count += 1;
            zonas[zona].dias.add(fecha);
        });

        return Object.entries(zonas).map(([nombre, data]) => {
            const diasTrabajados = data.dias.size;
            const promedioDiario = diasTrabajados > 0 ? data.total / diasTrabajados : 0;

            return {
                nombre,
                total: data.total,
                diasTrabajados,
                promedioDiario,
            };
        });
    }, [gananciasPorDia]);

    // Ordenar estadísticas
    const estadisticasOrdenadas = useMemo(() => {
        return [...estadisticas].sort((a, b) => {
            switch (sortBy) {
                case 'total': return b.total - a.total;
                case 'promedio': return b.promedioDiario - a.promedioDiario;
                case 'dias': return b.diasTrabajados - a.diasTrabajados;
                default: return b.total - a.total;
            }
        });
    }, [estadisticas, sortBy]);

    // Calcular total general
    const totalGeneral = useMemo(() => {
        return estadisticas.reduce((sum, zona) => sum + zona.total, 0);
    }, [estadisticas]);

    // Configurar y actualizar gráfico de pastel
    useEffect(() => {
        if (viewType === 'pie' && pieChartRef.current && estadisticas.length > 0) {
            if (pieChartInstance.current) {
                pieChartInstance.current.destroy();
            }

            const ctx = pieChartRef.current.getContext('2d');

            pieChartInstance.current = new Chart(ctx, {
                type: 'pie',
                data: {
                    labels: estadisticas.map(z => z.nombre),
                    datasets: [{
                        data: estadisticas.map(z => z.total),
                        backgroundColor: [
                            '#FF6384', '#36A2EB', '#FFCE56', '#4BC0C0',
                            '#9966FF', '#FF9F40', '#FF6384', '#C9CBCF',
                            '#4D5360', '#F7464A', '#949FB1', '#AC64AD'
                        ],
                        borderWidth: 2,
                        borderColor: '#fff'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'bottom',
                        },
                        tooltip: {
                            callbacks: {
                                label: function (context) {
                                    const label = context.label || '';
                                    const value = context.raw || 0;
                                    const percentage = ((value / totalGeneral) * 100).toFixed(1);
                                    return `${label}: $${value.toLocaleString()} (${percentage}%)`;
                                }
                            }
                        }
                    }
                }
            });
        }

        return () => {
            if (pieChartInstance.current) {
                pieChartInstance.current.destroy();
            }
        };
    }, [viewType, estadisticas, totalGeneral]);

    // Configurar y actualizar gráfico de barras
    useEffect(() => {
        if (viewType === 'bar' && barChartRef.current && estadisticas.length > 0) {
            if (barChartInstance.current) {
                barChartInstance.current.destroy();
            }

            const ctx = barChartRef.current.getContext('2d');

            barChartInstance.current = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: estadisticas.map(z => z.nombre),
                    datasets: [
                        {
                            label: 'Total Ganado',
                            data: estadisticas.map(z => z.total),
                            backgroundColor: 'rgba(54, 162, 235, 0.6)',
                            borderColor: 'rgba(54, 162, 235, 1)',
                            borderWidth: 1
                        },
                        {
                            label: 'Promedio Diario',
                            data: estadisticas.map(z => z.promedioDiario),
                            backgroundColor: 'rgba(255, 99, 132, 0.6)',
                            borderColor: 'rgba(255, 99, 132, 1)',
                            borderWidth: 1
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true,
                            ticks: {
                                callback: function (value) {
                                    return '$' + value.toLocaleString();
                                }
                            }
                        }
                    },
                    plugins: {
                        legend: {
                            position: 'bottom',
                        },
                        tooltip: {
                            callbacks: {
                                label: function (context) {
                                    let label = context.dataset.label || '';
                                    if (label) {
                                        label += ': ';
                                    }
                                    label += '$' + context.parsed.y.toLocaleString();
                                    return label;
                                }
                            }
                        }
                    }
                }
            });
        }

        return () => {
            if (barChartInstance.current) {
                barChartInstance.current.destroy();
            }
        };
    }, [viewType, estadisticas]);

    // Encontrar la mejor zona
    const mejorZona = estadisticasOrdenadas.length > 0 ? estadisticasOrdenadas[0] : null;

    if (estadisticas.length === 0) {
        return null; // No mostrar nada si no hay datos
    }

    return (
        <Box sx={{ mt: 3 }}>
            {/* Encabezado */}
            <Paper sx={{ p: 2, mb: 2, backgroundColor: '#e7f5ff' }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                    <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', gap: 1, color: '#1971c2' }}>
                        <LocationIcon /> Análisis por Zona de Venta
                    </Typography>

                    <Tooltip title="Total general">
                        <Chip
                            label={`Total: $${totalGeneral.toLocaleString()}`}
                            color="primary"
                            variant="outlined"
                        />
                    </Tooltip>
                </Box>

                <Typography variant="body2" color="text.secondary">
                    Analiza el rendimiento en cada zona para optimizar tus ventas
                </Typography>
            </Paper>

            {/* Controles */}
            <Paper sx={{ p: 2, mb: 2 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}>
                    <Box>
                        <Typography variant="subtitle2" gutterBottom>
                            Tipo de gráfico:
                        </Typography>
                        <ToggleButtonGroup
                            value={viewType}
                            exclusive
                            onChange={(e, newView) => newView && setViewType(newView)}
                            size="small"
                        >
                            <ToggleButton value="pie">
                                <PieChartIcon sx={{ mr: 1 }} /> Pastel
                            </ToggleButton>
                            <ToggleButton value="bar">
                                <BarChartIcon sx={{ mr: 1 }} /> Barras
                            </ToggleButton>
                        </ToggleButtonGroup>
                    </Box>

                    <Box>
                        <Typography variant="subtitle2" gutterBottom>
                            Ordenar por:
                        </Typography>
                        <ToggleButtonGroup
                            value={sortBy}
                            exclusive
                            onChange={(e, newSort) => newSort && setSortBy(newSort)}
                            size="small"
                        >
                            <ToggleButton value="total">Total</ToggleButton>
                            <ToggleButton value="promedio">Promedio</ToggleButton>
                            <ToggleButton value="dias">Días</ToggleButton>
                        </ToggleButtonGroup>
                    </Box>
                </Box>
            </Paper>

            {/* Mejor zona destacada */}
            {mejorZona && (
                <Paper sx={{
                    p: 2,
                    mb: 2,
                    backgroundColor: '#fff3bf',
                    border: '2px solid #ffd43b'
                }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                            <StarIcon sx={{ color: '#fcc419', fontSize: 32 }} />
                            <Box>
                                <Typography variant="h6" color="#e67700">
                                    🏆 Zona más productiva: {mejorZona.nombre}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                    {mejorZona.diasTrabajados} días trabajados •
                                    ${mejorZona.promedioDiario.toLocaleString('es-AR', { minimumFractionDigits: 0 })} promedio diario •
                                    Total: ${mejorZona.total.toLocaleString()}
                                </Typography>
                            </Box>
                        </Box>
                        <Chip
                            label={`${((mejorZona.total / totalGeneral) * 100).toFixed(1)}% del total`}
                            color="warning"
                            variant="filled"
                        />
                    </Box>
                </Paper>
            )}

            {/* Gráficos */}
            {viewType === 'pie' ? (
                <Paper sx={{ p: 2, height: 400, position: 'relative' }}>
                    <Typography variant="h6" gutterBottom align="center">
                        Distribución por Zona
                    </Typography>
                    <Box sx={{ height: 300, position: 'relative' }}>
                        <canvas ref={pieChartRef} />
                    </Box>
                    <Typography variant="caption" color="text.secondary" align="center" sx={{ mt: 1, display: 'block' }}>
                        Haz clic en la leyenda para filtrar zonas
                    </Typography>
                </Paper>
            ) : (
                <Paper sx={{ p: 2, height: 400, position: 'relative' }}>
                    <Typography variant="h6" gutterBottom align="center">
                        Comparativa de Zonas
                    </Typography>
                    <Box sx={{ height: 300, position: 'relative' }}>
                        <canvas ref={barChartRef} />
                    </Box>
                    <Typography variant="caption" color="text.secondary" align="center" sx={{ mt: 1, display: 'block' }}>
                        Barras azules: Total • Barras rosas: Promedio diario
                    </Typography>
                </Paper>
            )}
        </Box>
    );
};

export default EstadisticasZona;