// src/CobrosPage.js
import React from 'react';
import { Box, Typography } from '@mui/material';
import GestorCobros from './GestorCobros';

const CobrosPage = () => {
    return (
        <Box>
            <Typography variant="h4" fontWeight="bold" gutterBottom>💰 Gestión de Cobros</Typography>
            <Typography variant="body1" color="textSecondary" sx={{ mb: 3 }}>
                Administra los cobros pendientes y realizados
            </Typography>
            <GestorCobros />
        </Box>
    );
};

export default CobrosPage;