import React, { createContext, useContext, useState, useEffect, useMemo } from 'react';
import { createTheme } from '@mui/material/styles';

// Crear el contexto
const ThemeContext = createContext();

// Tipos de tema posibles
export const themeModes = {
    LIGHT: 'light',
    DARK: 'dark',
    SYSTEM: 'system'
};

// Función para obtener el tema real según la preferencia del sistema
const getSystemTheme = () => {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
};

// Hook personalizado para usar el contexto
export const useThemeContext = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useThemeContext must be used within ThemeProvider');
    }
    return context;
};

// Proveedor del tema
export const ThemeContextProvider = ({ children }) => {
    // Estado para guardar la preferencia del usuario
    const [mode, setMode] = useState(() => {
        const saved = localStorage.getItem('theme-mode');
        return saved && Object.values(themeModes).includes(saved) ? saved : themeModes.SYSTEM;
    });

    // Estado para el tema real actual (light o dark)
    const [actualTheme, setActualTheme] = useState(() => {
        if (mode === themeModes.SYSTEM) {
            return getSystemTheme();
        }
        return mode;
    });

    // Escuchar cambios en las preferencias del sistema
    useEffect(() => {
        const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

        const handleChange = (e) => {
            if (mode === themeModes.SYSTEM) {
                setActualTheme(e.matches ? 'dark' : 'light');
            }
        };

        mediaQuery.addEventListener('change', handleChange);
        return () => mediaQuery.removeEventListener('change', handleChange);
    }, [mode]);

    // Actualizar el tema real cuando cambie el modo
    useEffect(() => {
        if (mode === themeModes.SYSTEM) {
            setActualTheme(getSystemTheme());
        } else {
            setActualTheme(mode);
        }
        localStorage.setItem('theme-mode', mode);
    }, [mode]);

    // Cambiar el modo de tema
    const toggleMode = (newMode) => {
        if (Object.values(themeModes).includes(newMode)) {
            setMode(newMode);
        }
    };

    // Crear el tema de Material-UI según el tema actual
    const theme = useMemo(() => createTheme({
        typography: {
            fontFamily: 'Poppins, sans-serif',
            h1: {
                fontFamily: '"Fugaz One", cursive',
                fontWeight: 400,
                fontSize: '3rem',
                letterSpacing: '1px',
            },
            h2: {
                fontFamily: '"Fugaz One", cursive',
                fontWeight: 400,
                fontSize: '2.5rem',
                letterSpacing: '0.5px',
            },
            h3: {
                fontFamily: '"Maven pro", cursive',
                fontWeight: 400,
                fontSize: '2rem',
            },
            h4: {
                fontFamily: 'Maven pro, sans-serif',
                fontWeight: 600,
            },
            h5: {
                fontFamily: 'Maven pro, sans-serif',
                fontWeight: 400,
            },
            h6: {
                fontFamily: 'Poppins, sans-serif',
                fontWeight: 600,
            },
            button: {
                fontFamily: 'Poppins, sans-serif',
                fontWeight: 600,
            },
        },
        palette: {
            mode: actualTheme,
            ...(actualTheme === 'light' ? {
                primary: { main: '#1976d2' },
                secondary: { main: '#dc004e' },
                background: {
                    default: '#FFF9E6',
                    paper: '#FFFDF5',
                },
            } : {
                primary: { main: '#90caf9' },
                secondary: { main: '#f48fb1' },
                background: {
                    default: '#121212',
                    paper: '#1e1e1e',
                },
            }),
        },
        components: {
            MuiCssBaseline: {
                styleOverrides: {
                    body: {
                        fontFamily: 'Poppins, sans-serif',
                    },
                },
            },
            MuiPaper: {
                styleOverrides: {
                    root: {
                        backgroundImage: actualTheme === 'light'
                            ? 'linear-gradient(135deg, #FFFDF5 0%, #FFF9E6 100%)'
                            : 'linear-gradient(135deg, #1e1e1e 0%, #2a2a2a 100%)',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            transform: 'translateY(-2px)',
                            boxShadow: actualTheme === 'light'
                                ? '0 4px 12px rgba(0,0,0,0.1)'
                                : '0 4px 12px rgba(0,0,0,0.4)',
                        },
                    },
                },
            },
            MuiCard: {
                styleOverrides: {
                    root: {
                        borderRadius: '12px',
                        boxShadow: actualTheme === 'light'
                            ? '0 2px 8px rgba(0,0,0,0.06)'
                            : '0 2px 8px rgba(0,0,0,0.3)',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            transform: 'translateY(-2px)',
                            boxShadow: actualTheme === 'light'
                                ? '0 6px 16px rgba(0,0,0,0.1)'
                                : '0 6px 16px rgba(0,0,0,0.5)',
                        },
                    },
                },
            },
            MuiButton: {
                styleOverrides: {
                    root: {
                        borderRadius: '8px',
                        textTransform: 'none',
                        fontWeight: 600,
                    },
                },
            },
        },
    }), [actualTheme]);

    const value = {
        mode,
        actualTheme,
        theme, // <-- IMPORTANTE: Exportamos el theme
        toggleMode,
        themeModes
    };

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};