import React, { useState } from 'react';
import {
    IconButton, Menu, MenuItem, ListItemIcon, ListItemText,
    Divider, Box, Tooltip, useMediaQuery, useTheme
} from '@mui/material';
import {
    Brightness4, Brightness7, SettingsBrightness,
    LightMode, DarkMode, Computer
} from '@mui/icons-material';
import { useThemeContext, themeModes } from './ThemeContext';

const ThemeToggle = () => {
    const { mode, toggleMode, actualTheme } = useThemeContext();
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);
    const muiTheme = useTheme();
    const isMobile = useMediaQuery(muiTheme.breakpoints.down('sm'));

    const handleClick = (event) => {
        setAnchorEl(event.currentTarget);
    };

    const handleClose = () => {
        setAnchorEl(null);
    };

    const handleModeChange = (newMode) => {
        toggleMode(newMode);
        handleClose();
    };

    // Icono según el modo actual
    const getCurrentIcon = () => {
        if (mode === themeModes.LIGHT) return <LightMode />;
        if (mode === themeModes.DARK) return <DarkMode />;
        return <SettingsBrightness />;
    };

    // Tooltip según el modo actual
    const getTooltipText = () => {
        if (mode === themeModes.LIGHT) return 'Modo claro';
        if (mode === themeModes.DARK) return 'Modo oscuro';
        return 'Modo automático';
    };

    return (
        <>
            <Tooltip title={getTooltipText()} arrow>
                <IconButton
                    onClick={handleClick}
                    sx={{
                        backgroundColor: 'rgba(255,255,255,0.3)',
                        backdropFilter: 'blur(5px)',
                        color: actualTheme === 'light' ? '#1976d2' : '#90caf9',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            backgroundColor: actualTheme === 'light'
                                ? 'rgba(25, 118, 210, 0.2)'
                                : 'rgba(144, 202, 249, 0.2)',
                            transform: 'rotate(15deg)'
                        }
                    }}
                >
                    {getCurrentIcon()}
                </IconButton>
            </Tooltip>

            <Menu
                anchorEl={anchorEl}
                open={open}
                onClose={handleClose}
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'right',
                }}
                transformOrigin={{
                    vertical: 'top',
                    horizontal: 'right',
                }}
                PaperProps={{
                    sx: {
                        mt: 1,
                        minWidth: 200,
                        borderRadius: 2,
                        boxShadow: actualTheme === 'light'
                            ? '0 4px 20px rgba(0,0,0,0.1)'
                            : '0 4px 20px rgba(0,0,0,0.4)'
                    }
                }}
            >
                <MenuItem
                    onClick={() => handleModeChange(themeModes.LIGHT)}
                    selected={mode === themeModes.LIGHT}
                    sx={{ borderRadius: 1, mx: 0.5 }}
                >
                    <ListItemIcon>
                        <LightMode color={mode === themeModes.LIGHT ? 'primary' : 'inherit'} />
                    </ListItemIcon>
                    <ListItemText primary="Claro" />
                    {mode === themeModes.LIGHT && (
                        <Box component="span" sx={{ ml: 1, fontSize: '0.75rem', color: 'success.main' }}>✓</Box>
                    )}
                </MenuItem>

                <MenuItem
                    onClick={() => handleModeChange(themeModes.DARK)}
                    selected={mode === themeModes.DARK}
                    sx={{ borderRadius: 1, mx: 0.5 }}
                >
                    <ListItemIcon>
                        <DarkMode color={mode === themeModes.DARK ? 'primary' : 'inherit'} />
                    </ListItemIcon>
                    <ListItemText primary="Oscuro" />
                    {mode === themeModes.DARK && (
                        <Box component="span" sx={{ ml: 1, fontSize: '0.75rem', color: 'success.main' }}>✓</Box>
                    )}
                </MenuItem>

                <Divider sx={{ my: 0.5 }} />

                <MenuItem
                    onClick={() => handleModeChange(themeModes.SYSTEM)}
                    selected={mode === themeModes.SYSTEM}
                    sx={{ borderRadius: 1, mx: 0.5 }}
                >
                    <ListItemIcon>
                        <Computer color={mode === themeModes.SYSTEM ? 'primary' : 'inherit'} />
                    </ListItemIcon>
                    <ListItemText primary="Automático (sistema)" />
                    {mode === themeModes.SYSTEM && (
                        <Box component="span" sx={{ ml: 1, fontSize: '0.75rem', color: 'success.main' }}>✓</Box>
                    )}
                </MenuItem>
            </Menu>
        </>
    );
};

export default ThemeToggle;