import React, { useState, useRef, useEffect } from 'react';
import {
    Box, Toolbar, Typography, useMediaQuery, useTheme,
    Tabs, Tab, Divider, IconButton, Chip
} from '@mui/material';
import {
    Dashboard, PointOfSale, Inventory,
    BarChart, Payment, Refresh, WbSunny, Cloud, Thunderstorm,
    AcUnit, Grain, Opacity, MyLocation, WaterDrop
} from '@mui/icons-material';
import { useNavigate, useLocation } from 'react-router-dom';
import Footer from './Footer';
import ThemeToggle from './ThemeToggle';
import { useThemeContext } from './ThemeContext';

const menuItems = [
    { text: 'Dashboard', icon: <Dashboard />, path: '/' },
    { text: 'Ventas', icon: <PointOfSale />, path: '/ventas' },
    { text: 'Productos', icon: <Inventory />, path: '/productos' },
    { text: 'Estadísticas', icon: <BarChart />, path: '/estadisticas' },
    { text: 'Cobros', icon: <Payment />, path: '/cobros' },
];

// Componente para el clima
const WeatherWidget = () => {
    const [weather, setWeather] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [currentTime, setCurrentTime] = useState(new Date());
    const { actualTheme } = useThemeContext();

    const fetchWeather = async (city = null) => {
        try {
            let url = 'https://wttr.in/?format=j1';
            if (city) {
                url = `https://wttr.in/${city}?format=j1`;
            }

            const response = await fetch(url);
            const data = await response.json();

            if (data && data.current_condition && data.current_condition.length > 0) {
                const current = data.current_condition[0];
                const weatherDesc = current.lang_es && current.lang_es[0] ? current.lang_es[0].value : current.weatherDesc[0].value;

                setWeather({
                    temp: current.temp_C,
                    feelsLike: current.FeelsLikeC,
                    description: weatherDesc,
                    humidity: current.humidity,
                    wind: current.windspeedKmph,
                    code: current.weatherCode,
                    uv: current.uvIndex,
                    pressure: current.pressure
                });
                setError(null);
            } else {
                throw new Error('No se pudieron obtener los datos del clima');
            }
            setLoading(false);
        } catch (err) {
            console.error('Error obteniendo el clima:', err);
            setError('Error al cargar clima');
            setLoading(false);
        }
    };

    const getWeatherByLocation = () => {
        if (navigator.geolocation) {
            setLoading(true);
            navigator.geolocation.getCurrentPosition(async (position) => {
                try {
                    const { latitude, longitude } = position.coords;
                    const url = `https://wttr.in/${latitude},${longitude}?format=j1`;
                    const response = await fetch(url);
                    const data = await response.json();

                    if (data && data.current_condition && data.current_condition.length > 0) {
                        const current = data.current_condition[0];
                        const weatherDesc = current.lang_es && current.lang_es[0] ? current.lang_es[0].value : current.weatherDesc[0].value;

                        setWeather({
                            temp: current.temp_C,
                            feelsLike: current.FeelsLikeC,
                            description: weatherDesc,
                            humidity: current.humidity,
                            wind: current.windspeedKmph,
                            code: current.weatherCode,
                            uv: current.uvIndex,
                            pressure: current.pressure
                        });
                        setError(null);
                    } else {
                        fetchWeather('Buenos Aires');
                    }
                    setLoading(false);
                } catch (err) {
                    console.error('Error en geolocalización:', err);
                    fetchWeather('Buenos Aires');
                }
            }, () => {
                console.log('Permiso de ubicación denegado, usando ciudad por defecto');
                fetchWeather('Buenos Aires');
            });
        } else {
            fetchWeather('Buenos Aires');
        }
    };

    useEffect(() => {
        getWeatherByLocation();

        const timer = setInterval(() => {
            setCurrentTime(new Date());
        }, 60000);

        const weatherTimer = setInterval(() => {
            getWeatherByLocation();
        }, 1800000);

        return () => {
            clearInterval(timer);
            clearInterval(weatherTimer);
        };
    }, []);

    const getWeatherIcon = () => {
        if (!weather) return <WbSunny sx={{ fontSize: '1rem' }} />;

        const desc = weather.description.toLowerCase();

        if (desc.includes('lluvia') || desc.includes('llovizna') ||
            desc.includes('rain') || desc.includes('drizzle') ||
            desc.includes('chubasco') || desc.includes('chaparrón') ||
            desc.includes('tormenta') && desc.includes('lluvia')) {
            return <WaterDrop sx={{ fontSize: '1rem', color: '#4A90E2' }} />;
        }

        if (desc.includes('tormenta') || desc.includes('trueno') ||
            desc.includes('thunder') || desc.includes('storm')) {
            return <Thunderstorm sx={{ fontSize: '1rem', color: '#FFD700' }} />;
        }

        if (desc.includes('nieve') || desc.includes('snow') ||
            desc.includes('nevada')) {
            return <AcUnit sx={{ fontSize: '1rem', color: '#87CEEB' }} />;
        }

        if (desc.includes('niebla') || desc.includes('bruma') ||
            desc.includes('fog') || desc.includes('mist')) {
            return <Opacity sx={{ fontSize: '1rem', color: '#9E9E9E' }} />;
        }

        if (desc.includes('nublado') || desc.includes('nubes') ||
            desc.includes('cloud') || desc.includes('overcast')) {
            return <Cloud sx={{ fontSize: '1rem', color: '#757575' }} />;
        }

        if (desc.includes('mayormente nublado') || desc.includes('parcialmente nublado')) {
            return <Cloud sx={{ fontSize: '1rem', color: '#9E9E9E' }} />;
        }

        if (desc.includes('despejado') || desc.includes('soleado') ||
            desc.includes('clear') || desc.includes('sunny')) {
            return <WbSunny sx={{ fontSize: '1rem', color: '#FFC107' }} />;
        }

        return <WbSunny sx={{ fontSize: '1rem' }} />;
    };

    const formatDate = () => {
        const options = {
            weekday: 'short',
            month: 'short',
            day: 'numeric'
        };
        return currentTime.toLocaleDateString('es-ES', options);
    };

    const formatTime = () => {
        return currentTime.toLocaleTimeString('es-ES', {
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    if (loading) {
        return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, opacity: 0.7 }}>
                <Chip
                    size="small"
                    icon={<MyLocation sx={{ fontSize: '0.8rem' }} />}
                    label="Clima..."
                    sx={{ height: 24, fontSize: '0.7rem' }}
                />
            </Box>
        );
    }

    if (error) {
        return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                <Chip
                    size="small"
                    label="Sin clima"
                    sx={{ height: 24, fontSize: '0.7rem' }}
                />
            </Box>
        );
    }

    return (
        <Box sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 1,
            backgroundColor: actualTheme === 'light' ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.3)',
            backdropFilter: 'blur(4px)',
            borderRadius: 2,
            padding: '4px 8px',
            border: `1px solid ${actualTheme === 'light' ? 'rgba(255,255,255,0.4)' : 'rgba(255,255,255,0.1)'}`,
            transition: 'all 0.3s ease',
            '&:hover': {
                backgroundColor: actualTheme === 'light' ? 'rgba(255,255,255,0.5)' : 'rgba(255,255,255,0.1)',
                transform: 'scale(1.02)'
            }
        }}>
            <Box sx={{ textAlign: 'right' }}>
                <Typography variant="caption" sx={{
                    fontSize: '0.65rem',
                    display: 'block',
                    lineHeight: 1.2,
                    color: actualTheme === 'light' ? '#444' : '#ccc'
                }}>
                    {formatDate()}
                </Typography>
                <Typography variant="caption" sx={{
                    fontSize: '0.7rem',
                    fontWeight: 'bold',
                    display: 'block',
                    color: '#1976d2'
                }}>
                    {formatTime()}
                </Typography>
            </Box>

            <Divider orientation="vertical" flexItem sx={{ backgroundColor: actualTheme === 'light' ? 'rgba(0,0,0,0.2)' : 'rgba(255,255,255,0.2)' }} />

            <Box sx={{
                display: 'flex',
                flexDirection: { xs: 'column', sm: 'row' },
                alignItems: 'center',
                gap: { xs: 0.5, sm: 0.5 }
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    {getWeatherIcon()}
                    <Typography variant="body2" sx={{ fontWeight: 'bold', fontSize: '0.8rem', color: actualTheme === 'light' ? '#333' : '#eee' }}>
                        {weather?.temp}°C
                    </Typography>
                </Box>

                <Typography variant="caption" sx={{
                    fontSize: '0.65rem',
                    color: actualTheme === 'light' ? '#555' : '#aaa',
                    textAlign: 'center',
                    maxWidth: { xs: '100%', sm: '100px' },
                    whiteSpace: { xs: 'normal', sm: 'nowrap' },
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    display: 'block',
                    lineHeight: 1.2
                }}>
                    {weather?.description}
                </Typography>
            </Box>
        </Box>
    );
};

const Layout = ({ children }) => {
    const theme = useTheme();
    const { actualTheme } = useThemeContext();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const navigate = useNavigate();
    const location = useLocation();

    const swipeContainerRef = useRef(null);

    const touchStartX = useRef(0);
    const touchStartY = useRef(0);
    const touchEndX = useRef(0);
    const touchEndY = useRef(0);
    const isSwiping = useRef(false);

    const currentTab = menuItems.findIndex(item => item.path === location.pathname);
    const [tabValue, setTabValue] = useState(currentTab !== -1 ? currentTab : 0);

    const handleTabChange = (event, newValue) => {
        setTabValue(newValue);
        navigate(menuItems[newValue].path);
    };

    const handleTouchStart = (e) => {
        const target = e.target;
        const isInteractive = target.closest('input, button, textarea, select, [role="slider"], .MuiSlider-root');
        const isScrollable = target.closest('[style*="overflow: auto"], [style*="overflow-x: auto"], [style*="overflow-y: auto"]');
        const isScrollableElement = target.closest('.MuiTable-root, .MuiList-root, .MuiDataGrid-root, .product-list, .scrollable-content');

        if (!isInteractive && !isScrollable && !isScrollableElement) {
            touchStartX.current = e.touches[0].clientX;
            touchStartY.current = e.touches[0].clientY;
            isSwiping.current = false;
        } else {
            touchStartX.current = 0;
            touchStartY.current = 0;
            isSwiping.current = false;
        }
    };

    const handleTouchMove = (e) => {
        if (touchStartX.current !== 0 && touchStartY.current !== 0) {
            const currentX = e.touches[0].clientX;
            const currentY = e.touches[0].clientY;
            const deltaX = Math.abs(currentX - touchStartX.current);
            const deltaY = Math.abs(currentY - touchStartY.current);

            if (deltaY > deltaX && deltaY > 10) {
                isSwiping.current = false;
                touchStartX.current = 0;
                touchStartY.current = 0;
                return;
            }

            if (deltaX > deltaY && deltaX > 10) {
                isSwiping.current = true;
                e.preventDefault();
            }

            touchEndX.current = currentX;
            touchEndY.current = currentY;
        }
    };

    const handleTouchEnd = () => {
        if (!touchStartX.current || !touchEndX.current || !isSwiping.current) {
            touchStartX.current = 0;
            touchStartY.current = 0;
            touchEndX.current = 0;
            touchEndY.current = 0;
            isSwiping.current = false;
            return;
        }

        const deltaX = touchEndX.current - touchStartX.current;
        const minSwipeDistance = 50;

        if (Math.abs(deltaX) > minSwipeDistance) {
            if (deltaX > 0 && tabValue > 0) {
                handleTabChange(null, tabValue - 1);
            } else if (deltaX < 0 && tabValue < menuItems.length - 1) {
                handleTabChange(null, tabValue + 1);
            }
        }

        touchStartX.current = 0;
        touchStartY.current = 0;
        touchEndX.current = 0;
        touchEndY.current = 0;
        isSwiping.current = false;
    };

    const handleMouseDown = (e) => {
        if (e.button === 0) {
            touchStartX.current = e.clientX;
            touchStartY.current = e.clientY;
            isSwiping.current = false;
        }
    };

    const handleMouseMove = (e) => {
        if (touchStartX.current !== 0 && touchStartY.current !== 0) {
            const deltaX = Math.abs(e.clientX - touchStartX.current);
            const deltaY = Math.abs(e.clientY - touchStartY.current);

            if (deltaY > deltaX && deltaY > 10) {
                isSwiping.current = false;
                touchStartX.current = 0;
                touchStartY.current = 0;
                return;
            }

            if (deltaX > deltaY && deltaX > 10) {
                isSwiping.current = true;
            }

            touchEndX.current = e.clientX;
            touchEndY.current = e.clientY;
        }
    };

    const handleMouseUp = () => {
        if (touchStartX.current !== 0 && touchEndX.current !== 0 && isSwiping.current) {
            const deltaX = touchEndX.current - touchStartX.current;
            const minSwipeDistance = 50;

            if (Math.abs(deltaX) > minSwipeDistance) {
                if (deltaX > 0 && tabValue > 0) {
                    handleTabChange(null, tabValue - 1);
                } else if (deltaX < 0 && tabValue < menuItems.length - 1) {
                    handleTabChange(null, tabValue + 1);
                }
            }
        }

        touchStartX.current = 0;
        touchStartY.current = 0;
        touchEndX.current = 0;
        touchEndY.current = 0;
        isSwiping.current = false;
    };

    const handleRefresh = () => {
        window.location.reload();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh', position: 'relative' }}>
            {/* Fondo de la aplicación */}
            <Box sx={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                background: actualTheme === 'light'
                    ? 'linear-gradient(135deg, #FFF9E6 0%, #FFF5D4 50%, #FFF9E6 100%)'
                    : 'linear-gradient(135deg, #121212 0%, #1a1a2e 50%, #121212 100%)',
                zIndex: 0,
            }} />

            {/* Barra superior */}
            <Box
                component="header"
                sx={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    zIndex: 1100,
                    backgroundColor: actualTheme === 'light' ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.5)',
                    backdropFilter: 'blur(3px)',
                    WebkitBackdropFilter: 'blur(3px)',
                    borderBottom: `1px solid ${actualTheme === 'light' ? 'rgba(255, 255, 255, 0.4)' : 'rgba(255, 255, 255, 0.1)'}`,
                    boxShadow: '0 4px 30px rgba(0, 0, 0, 0.05)',
                }}
            >
                <Toolbar sx={{
                    flexDirection: 'column',
                    alignItems: 'stretch',
                    p: { xs: 1.5, sm: 2 },
                    minHeight: { xs: 'auto', sm: 'auto' },
                    backgroundColor: 'transparent',
                }}>
                    {/* Fila superior con título y clima */}
                    <Box sx={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        mb: { xs: 1, sm: 1.5 },
                        px: { xs: 1, sm: 2 }
                    }}>
                        <Box sx={{ width: { xs: 'auto', sm: 'auto' } }} />

                        <Typography
                            variant="h6"
                            sx={{
                                fontWeight: 'bold',
                                background: 'linear-gradient(135deg, #1976d2, #9c27b0)',
                                backgroundClip: 'text',
                                WebkitBackgroundClip: 'text',
                                color: 'transparent',
                                fontSize: { xs: '1rem', sm: '1.25rem' },
                                textAlign: 'center',
                                textShadow: '0 2px 10px rgba(0,0,0,0.05)'
                            }}
                        >
                            Mi Aplicación
                        </Typography>

                        {/* Widget de clima y fecha en la esquina derecha */}
                        <WeatherWidget />
                    </Box>

                    {/* Divider */}
                    <Divider sx={{
                        my: 1,
                        borderBottomWidth: 2,
                        background: 'linear-gradient(90deg, rgba(111, 25, 210, 0.2), rgba(45, 52, 148, 0.6), rgba(0, 128, 255, 0.2))',
                        height: '3px',
                    }} />

                    {/* Pestañas de navegación - CORREGIDO: Toggle a la izquierda, Refresh a la derecha */}
                    <Box sx={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        width: '100%'
                    }}>
                        {/* ThemeToggle a la izquierda */}
                        <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', width: 48 }}>
                            <ThemeToggle />
                        </Box>

                        {/* Tabs centrados */}
                        <Box sx={{ display: 'flex', justifyContent: 'center', flex: 1 }}>
                            <Tabs
                                value={tabValue}
                                onChange={handleTabChange}
                                variant="scrollable"
                                scrollButtons="auto"
                                allowScrollButtonsMobile
                                sx={{
                                    minHeight: { xs: 48, sm: 56 },
                                    '& .MuiTab-root': {
                                        minHeight: { xs: 48, sm: 56 },
                                        textTransform: 'none',
                                        fontWeight: 600,
                                        fontSize: { xs: '0.75rem', sm: '0.875rem' },
                                        color: actualTheme === 'light' ? '#444' : '#ddd',
                                        transition: 'all 0.3s ease',
                                        '&:hover': {
                                            color: '#1976d2',
                                            transform: 'translateY(-2px)'
                                        },
                                        '&.Mui-selected': {
                                            color: '#9c27b0',
                                            fontWeight: 700,
                                        }
                                    },
                                    '& .MuiTabs-indicator': {
                                        backgroundColor: '#9c27b0',
                                        height: 3,
                                        borderRadius: '3px 3px 0 0',
                                        background: 'linear-gradient(90deg, #1976d2, #9c27b0)'
                                    }
                                }}
                            >
                                {menuItems.map((item) => (
                                    <Tab
                                        key={item.path}
                                        icon={item.icon}
                                        label={!isMobile ? item.text : null}
                                        iconPosition="top"
                                        sx={{
                                            minWidth: { xs: 'auto', sm: 90 },
                                            px: { xs: 1.5, sm: 2 },
                                        }}
                                    />
                                ))}
                            </Tabs>
                        </Box>

                        {/* Refresh a la derecha */}
                        <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', width: 48, justifyContent: 'flex-end' }}>
                            <IconButton
                                onClick={handleRefresh}
                                sx={{
                                    backgroundColor: actualTheme === 'light' ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.3)',
                                    backdropFilter: 'blur(5px)',
                                    color: actualTheme === 'light' ? '#1976d2' : '#90caf9',
                                    '&:hover': {
                                        backgroundColor: actualTheme === 'light'
                                            ? 'rgba(25, 118, 210, 0.2)'
                                            : 'rgba(144, 202, 249, 0.2)',
                                        transform: 'rotate(180deg)',
                                        transition: 'transform 0.5s ease'
                                    }
                                }}
                            >
                                <Refresh />
                            </IconButton>
                        </Box>
                    </Box>
                </Toolbar>
            </Box>

            {/* Espaciador */}
            <Box sx={{ height: { xs: '130px', sm: '150px' } }} />

            {/* Contenido principal */}
            <Box
                ref={swipeContainerRef}
                component="main"
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                sx={{
                    flexGrow: 1,
                    mt: 2,
                    p: { xs: 2, sm: 3 },
                    position: 'relative',
                    zIndex: 1,
                    backgroundColor: 'transparent',
                    cursor: 'grab',
                    '&:active': {
                        cursor: 'grabbing',
                    },
                    touchAction: 'pan-y pinch-zoom',
                }}
            >
                {children}
            </Box>
            <Footer />
        </Box>
    );
};

export default Layout;