// src/VentasPage.js
import React, { useState, useEffect } from 'react';
import { Box, Typography, Paper } from '@mui/material';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";
import RegistroVentas from './RegistroVentas';
import HistorialVentas from './HistorialVentas';

const VentasPage = () => {
    const [gananciasPorDia, setGananciasPorDia] = useState([]);

    const cargarGanancias = async () => {
        const gananciasRef = ref(db, "ganancias/historial");
        const snapshot = await get(gananciasRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const currentYear = new Date().getFullYear();
            const currentMonth = new Date().getMonth();
            const mesFiltrado = Object.values(data).filter(g => {
                const fecha = new Date(g.fechaGanancia);
                return fecha.getMonth() === currentMonth && fecha.getFullYear() === currentYear;
            });
            setGananciasPorDia(mesFiltrado);
        }
    };

    useEffect(() => { cargarGanancias(); }, []);

    return (
        <Box>
            <Typography variant="h4" fontWeight="bold" gutterBottom>📝 Registrar Ventas</Typography>
            <RegistroVentas onVentaRegistrada={cargarGanancias} />
            <Box sx={{ mt: 4 }}><HistorialVentas onRefresh={cargarGanancias} /></Box>
            <Typography variant="h6" sx={{ mt: 4, mb: 2 }}>📋 Ingresos Diarios del Mes</Typography>
            {gananciasPorDia.length === 0 ? (
                <Typography textAlign="center">No hay ganancias registradas este mes.</Typography>
            ) : (
                gananciasPorDia.sort((a, b) => b.total - a.total).map((g, index) => (
                    <Paper key={index} sx={{ p: 2, mb: 1 }}>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                            <Box>
                                <Typography fontWeight="bold">{new Date(g.fechaGanancia).toLocaleDateString()}</Typography>
                                <Typography variant="body2">👤 Cliente: {g.cliente || "No especificado"}</Typography>
                                {g.zona && <Typography variant="body2">📍 Zona: {g.zona}</Typography>}
                            </Box>
                            <Typography fontWeight="bold" color="#2e7d32">${g.total.toLocaleString()}</Typography>
                        </Box>
                    </Paper>
                ))
            )}
        </Box>
    );
};

export default VentasPage;