// src/components/Ganancias/Proyecciones.js
import React, { useState } from 'react';
import { Box, Typography, TextField, Button } from '@mui/material';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';

const Proyecciones = ({
    totalGanancias,
    diasTrabajados,
    gananciasPorMes = [],
    mesActual
}) => {
    const [metaDiaria, setMetaDiaria] = useState(50000);
    const [editandoMeta, setEditandoMeta] = useState(false);

    // Calcular proyecciones
    const calcularProyecciones = () => {
        const promedioDiario = diasTrabajados > 0 ? totalGanancias / diasTrabajados : 0;

        // Calcular días restantes del mes
        const hoy = new Date();
        const ultimoDiaMes = new Date(hoy.getFullYear(), mesActual + 1, 0);
        const diasEnMes = ultimoDiaMes.getDate();
        const diasTranscurridos = hoy.getDate();
        const diasRestantes = diasEnMes - diasTranscurridos;

        const proyeccionFinMes = totalGanancias + (promedioDiario * diasRestantes);
        const eficienciaVsMeta = metaDiaria > 0 ? (promedioDiario / metaDiaria) * 100 : 0;

        // Días para alcanzar metas
        const diasPara800k = promedioDiario > 0
            ? Math.max(0, Math.ceil((800000 - totalGanancias) / promedioDiario))
            : '∞';

        const diasPara1M = promedioDiario > 0
            ? Math.max(0, Math.ceil((1000000 - totalGanancias) / promedioDiario))
            : '∞';

        return {
            promedioDiario,
            diasRestantes,
            proyeccionFinMes,
            eficienciaVsMeta,
            diasPara800k,
            diasPara1M,
            faltante800k: Math.max(0, 800000 - totalGanancias),
            faltante1M: Math.max(0, 1000000 - totalGanancias)
        };
    };

    const proyecciones = calcularProyecciones();

    const obtenerNombreMes = (mes) => {
        const nombresMeses = [
            "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
            "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
        ];
        return nombresMeses[mes] || "Desconocido";
    };

    return (
        <Box sx={{
            mt: 3,
            p: 2,
            borderRadius: 2,
            boxShadow: 2,
            backgroundColor: '#f8f9fa',
            border: '1px solid #e9ecef'
        }}>
            {/* Encabezado con ajuste de meta */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6" sx={{ color: '#084a4e', display: 'flex', alignItems: 'center', gap: 1 }}>
                    📈 Proyecciones del Mes
                </Typography>

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    {editandoMeta ? (
                        <>
                            <TextField
                                size="small"
                                type="number"
                                value={metaDiaria}
                                onChange={(e) => setMetaDiaria(Number(e.target.value))}
                                sx={{ width: 100 }}
                                label="Meta diaria"
                            />
                            <Button size="small" onClick={() => setEditandoMeta(false)} variant="contained">
                                ✓
                            </Button>
                        </>
                    ) : (
                        <>
                            <Typography variant="caption" color="text.secondary">
                                Meta: ${metaDiaria.toLocaleString()}
                            </Typography>
                            <Button size="small" onClick={() => setEditandoMeta(true)}>
                                ✏️
                            </Button>
                        </>
                    )}
                </Box>
            </Box>

            {/* Estadísticas principales */}
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(3, 1fr)' }, gap: 2 }}>
                {/* Promedio Diario */}
                <Box sx={{
                    p: 2,
                    borderRadius: 1,
                    backgroundColor: 'white',
                    boxShadow: 1,
                    textAlign: 'center'
                }}>
                    <Typography variant="subtitle2" color="text.secondary">
                        Promedio Diario
                    </Typography>
                    <Typography variant="h6" color="primary" fontWeight="bold">
                        ${proyecciones.promedioDiario.toLocaleString('es-AR', {
                            minimumFractionDigits: 0,
                            maximumFractionDigits: 0
                        })}
                    </Typography>
                    <Typography variant="caption" sx={{
                        color: proyecciones.eficienciaVsMeta >= 100 ? 'green' :
                            proyecciones.eficienciaVsMeta >= 80 ? 'orange' : 'red'
                    }}>
                        {proyecciones.eficienciaVsMeta.toFixed(1)}% de la meta
                    </Typography>
                </Box>

                {/* Días Restantes */}
                <Box sx={{
                    p: 2,
                    borderRadius: 1,
                    backgroundColor: 'white',
                    boxShadow: 1,
                    textAlign: 'center'
                }}>
                    <Typography variant="subtitle2" color="text.secondary">
                        Días Restantes
                    </Typography>
                    <Typography variant="h6" fontWeight="bold" sx={{
                        color: proyecciones.diasRestantes <= 7 ? '#ff6b6b' : '#339af0'
                    }}>
                        {proyecciones.diasRestantes} días
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        {obtenerNombreMes(mesActual)}
                    </Typography>
                </Box>

                {/* Proyección Fin de Mes */}
                <Box sx={{
                    p: 2,
                    borderRadius: 1,
                    backgroundColor: 'white',
                    boxShadow: 1,
                    textAlign: 'center'
                }}>
                    <Typography variant="subtitle2" color="text.secondary">
                        Proyección Final
                    </Typography>
                    <Typography variant="h6" fontWeight="bold" color="#fa5252">
                        ${proyecciones.proyeccionFinMes.toLocaleString('es-AR', {
                            minimumFractionDigits: 0,
                            maximumFractionDigits: 0
                        })}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        Basado en promedio
                    </Typography>
                </Box>
            </Box>

            {/* Metas a alcanzar */}
            <Box sx={{
                mt: 3,
                p: 2,
                borderRadius: 1,
                backgroundColor: '#fff9db',
                border: '1px solid #ffd43b'
            }}>
                <Typography variant="subtitle1" fontWeight="bold" gutterBottom sx={{ color: '#5c940d' }}>
                    🎯 Metas por Alcanzar
                </Typography>

                <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 2 }}>
                    {/* Meta $800k */}
                    <Box sx={{
                        p: 1.5,
                        borderRadius: 1,
                        backgroundColor: 'white',
                        boxShadow: 1
                    }}>
                        <Typography variant="body2" color="text.secondary">
                            Para $800k
                        </Typography>
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <Typography variant="h6" fontWeight="bold" color="#fd7e14">
                                {typeof proyecciones.diasPara800k === 'number'
                                    ? `${proyecciones.diasPara800k} días`
                                    : proyecciones.diasPara800k}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                                Faltan: ${proyecciones.faltante800k.toLocaleString()}
                            </Typography>
                        </Box>
                        <Box sx={{
                            width: '100%',
                            height: 4,
                            backgroundColor: '#e9ecef',
                            borderRadius: 2,
                            mt: 1,
                            overflow: 'hidden'
                        }}>
                            <Box sx={{
                                width: `${Math.min(100, (totalGanancias / 800000) * 100)}%`,
                                height: '100%',
                                backgroundColor: '#fd7e14'
                            }} />
                        </Box>
                    </Box>

                    {/* Meta $1M */}
                    <Box sx={{
                        p: 1.5,
                        borderRadius: 1,
                        backgroundColor: 'white',
                        boxShadow: 1
                    }}>
                        <Typography variant="body2" color="text.secondary">
                            Para $1M
                        </Typography>
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <Typography variant="h6" fontWeight="bold" color="#e03131">
                                {typeof proyecciones.diasPara1M === 'number'
                                    ? `${proyecciones.diasPara1M} días`
                                    : proyecciones.diasPara1M}
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                                Faltan: ${proyecciones.faltante1M.toLocaleString()}
                            </Typography>
                        </Box>
                        <Box sx={{
                            width: '100%',
                            height: 4,
                            backgroundColor: '#e9ecef',
                            borderRadius: 2,
                            mt: 1,
                            overflow: 'hidden'
                        }}>
                            <Box sx={{
                                width: `${Math.min(100, (totalGanancias / 1000000) * 100)}%`,
                                height: '100%',
                                backgroundColor: '#e03131'
                            }} />
                        </Box>
                    </Box>
                </Box>
            </Box>

            {/* Consejo basado en proyección */}
            <Box sx={{ mt: 2, p: 1.5, backgroundColor: '#e7f5ff', borderRadius: 1 }}>
                <Typography variant="body2" fontWeight="bold" color="#1971c2" gutterBottom>
                    💡 Consejo del día:
                </Typography>
                <Typography variant="body2">
                    {proyecciones.eficienciaVsMeta >= 100
                        ? '¡Excelente! Estás superando tu meta diaria. Mantén este ritmo.'
                        : proyecciones.eficienciaVsMeta >= 80
                            ? 'Casi alcanzas tu meta. Un pequeño esfuerzo más y la superarás.'
                            : 'Intenta aumentar tu promedio a la meta para alcanzar tus objetivos mensuales.'}
                </Typography>
            </Box>
        </Box>
    );
};

export default Proyecciones;