// src/WidgetCobrosPendientes.js
import React, { useState, useEffect } from 'react';
import {
    Box,
    Typography,
    Paper,
    Card,
    CardContent,
    Button,
    Chip,
    List,
    ListItem,
    ListItemText,
    Divider,
    IconButton,
    Collapse,
    Alert,
    Badge
} from '@mui/material';
import {
    Warning as WarningIcon,
    TrendingUp as TrendingUpIcon,
    AttachMoney as AttachMoneyIcon,
    ExpandMore as ExpandMoreIcon,
    ExpandLess as ExpandLessIcon,
    NotificationsActive as NotificationsActiveIcon
} from '@mui/icons-material';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";
import { useNavigate } from 'react-router-dom';

const WidgetCobrosPendientes = () => {
    const navigate = useNavigate();
    const [cobrosPendientesHoy, setCobrosPendientesHoy] = useState([]);
    const [cobrosVencidos, setCobrosVencidos] = useState([]);
    const [expandido, setExpandido] = useState(false); // Cambiado a false por defecto
    const [totalPendientes, setTotalPendientes] = useState(0);
    const [totalVencido, setTotalVencido] = useState(0);
    const [totalHoy, setTotalHoy] = useState(0);

    const cargarCobros = async () => {
        const cobrosRef = ref(db, "cobros");
        const snapshot = await get(cobrosRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const cobrosList = Object.entries(data).map(([id, cobro]) => ({
                id,
                ...cobro
            }));

            const hoy = new Date();
            hoy.setHours(0, 0, 0, 0);

            const pendientes = cobrosList.filter(c => c.estado !== 'cobrado');

            const paraHoy = pendientes.filter(cobro => {
                const fechaCobro = new Date(cobro.fechaCobro);
                fechaCobro.setHours(0, 0, 0, 0);
                return fechaCobro.getTime() === hoy.getTime();
            });

            const vencidos = pendientes.filter(cobro => {
                const fechaCobro = new Date(cobro.fechaCobro);
                fechaCobro.setHours(0, 0, 0, 0);
                return fechaCobro.getTime() < hoy.getTime();
            });

            setCobrosPendientesHoy(paraHoy);
            setCobrosVencidos(vencidos);
            setTotalPendientes(pendientes.length);
            setTotalVencido(vencidos.reduce((sum, c) => sum + c.monto, 0));
            setTotalHoy(paraHoy.reduce((sum, c) => sum + c.monto, 0));
        }
    };

    useEffect(() => {
        cargarCobros();
        const interval = setInterval(cargarCobros, 60000);
        return () => clearInterval(interval);
    }, []);

    const irACobros = () => {
        navigate('/cobros');
    };

    if (totalPendientes === 0) {
        return null;
    }

    return (
        <Card sx={{
            mb: 3,
            background: cobrosVencidos.length > 0
                ? 'linear-gradient(135deg, #fff5f5 0%, #ffe0e0 100%)'
                : 'linear-gradient(135deg, #fff8e7 0%, #fff0d4 100%)',
            border: cobrosVencidos.length > 0 ? '2px solid #f44336' : '2px solid #ff9800',
            borderRadius: 3,
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        }}>
            <CardContent sx={{ p: 2 }}>
                {/* Encabezado colapsable - solo chips */}
                <Box
                    sx={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        cursor: 'pointer'
                    }}
                    onClick={() => setExpandido(!expandido)}
                >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                        {cobrosVencidos.length > 0 && (
                            <Chip
                                icon={<WarningIcon />}
                                label={`${cobrosVencidos.length} VENCIDO(S)`}
                                color="error"
                                sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}
                            />
                        )}
                        {cobrosPendientesHoy.length > 0 && (
                            <Chip
                                icon={<TrendingUpIcon />}
                                label={`${cobrosPendientesHoy.length} para HOY`}
                                color="warning"
                                sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}
                            />
                        )}
                        {totalPendientes > 0 && (
                            <Chip
                                icon={<AttachMoneyIcon />}
                                label={`$${totalVencido > 0 ? totalVencido.toLocaleString() : totalHoy.toLocaleString()} pendiente`}
                                variant="outlined"
                                sx={{ fontSize: '0.85rem' }}
                            />
                        )}
                    </Box>
                    <IconButton size="small">
                        {expandido ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                    </IconButton>
                </Box>

                {/* Detalles expandibles */}
                <Collapse in={expandido}>
                    {/* Cobros Vencidos */}
                    {cobrosVencidos.length > 0 && (
                        <>
                            <Alert severity="error" sx={{ mb: 2, mt: 2 }}>
                                <Typography variant="body2" fontWeight="bold">
                                    ❗ Total adeudado vencido: ${totalVencido.toLocaleString()}
                                </Typography>
                            </Alert>

                            <List dense sx={{ maxHeight: 200, overflow: 'auto' }}>
                                {cobrosVencidos.slice(0, 5).map((cobro) => (
                                    <ListItem key={cobro.id} sx={{ pl: 0 }}>
                                        <ListItemText
                                            primary={
                                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                    <Typography variant="body2" fontWeight="bold" color="#c62828">
                                                        {cobro.cliente}
                                                    </Typography>
                                                    <Typography variant="body2" color="#c62828" fontWeight="bold">
                                                        ${cobro.monto.toLocaleString()}
                                                    </Typography>
                                                </Box>
                                            }
                                            secondary={`Vencido: ${new Date(cobro.fechaCobro).toLocaleDateString()}`}
                                        />
                                    </ListItem>
                                ))}
                                {cobrosVencidos.length > 5 && (
                                    <Typography variant="caption" color="textSecondary" sx={{ display: 'block', textAlign: 'center' }}>
                                        ... y {cobrosVencidos.length - 5} más
                                    </Typography>
                                )}
                            </List>
                        </>
                    )}

                    {/* Cobros para hoy */}
                    {cobrosPendientesHoy.length > 0 && (
                        <>
                            {cobrosVencidos.length > 0 && <Divider sx={{ my: 1 }} />}
                            <Alert severity="warning" sx={{ mb: 2, mt: cobrosVencidos.length > 0 ? 1 : 2 }}>
                                <Typography variant="body2" fontWeight="bold">
                                    💰 Total a cobrar hoy: ${totalHoy.toLocaleString()}
                                </Typography>
                            </Alert>

                            <List dense>
                                {cobrosPendientesHoy.map((cobro) => (
                                    <ListItem key={cobro.id} sx={{ pl: 0 }}>
                                        <ListItemText
                                            primary={
                                                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                    <Typography variant="body2" fontWeight="bold">
                                                        {cobro.cliente}
                                                    </Typography>
                                                    <Typography variant="body2" color="#ff9800" fontWeight="bold">
                                                        ${cobro.monto.toLocaleString()}
                                                    </Typography>
                                                </Box>
                                            }
                                            secondary={cobro.zona && `📍 ${cobro.zona}`}
                                        />
                                    </ListItem>
                                ))}
                            </List>
                        </>
                    )}

                    <Button
                        variant="contained"
                        size="small"
                        fullWidth
                        onClick={irACobros}
                        sx={{ mt: 2 }}
                        color={cobrosVencidos.length > 0 ? 'error' : 'warning'}
                    >
                        {cobrosVencidos.length > 0 ? 'Ver Cobros Vencidos' : 'Ver Todos los Cobros'}
                    </Button>
                </Collapse>
            </CardContent>
        </Card>
    );
};

export default WidgetCobrosPendientes;