// src/components/Ganancias/HistorialVentas.js
import React, { useState, useEffect } from 'react';
import {
    Box, Typography, Paper, Table, TableBody, TableCell, TableContainer,
    TableHead, TableRow, Chip, IconButton, Collapse, TextField,
    Select, MenuItem, FormControl, InputLabel, Button, Alert,
    Dialog, DialogTitle, DialogContent, DialogActions, Tooltip,
    useMediaQuery, useTheme, Card, CardContent, Stack, Divider, Snackbar
} from '@mui/material';
import { ref, get, onValue, remove, update } from "firebase/database";
import { db } from "./firebaseConfig";
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowUpIcon from '@mui/icons-material/KeyboardArrowUp';
import ReceiptIcon from '@mui/icons-material/Receipt';
import RefreshIcon from '@mui/icons-material/Refresh';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import FilterListIcon from '@mui/icons-material/FilterList';
import SaveIcon from '@mui/icons-material/Save';
import CloseIcon from '@mui/icons-material/Close';

const HistorialVentas = ({ onRefresh }) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

    const [ventas, setVentas] = useState([]);
    const [filtroCliente, setFiltroCliente] = useState('');
    const [filtroZona, setFiltroZona] = useState('');
    const [filtroFecha, setFiltroFecha] = useState('');
    const [zonas, setZonas] = useState([]);
    const [loading, setLoading] = useState(true);
    const [mostrarFiltros, setMostrarFiltros] = useState(false);

    // Estados para edición
    const [editandoVenta, setEditandoVenta] = useState(null);
    const [ventaEdit, setVentaEdit] = useState({});
    const [dialogOpen, setDialogOpen] = useState(false);

    const cargarVentas = async () => {
        setLoading(true);
        const ventasRef = ref(db, "ventas");
        const snapshot = await get(ventasRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const ventasList = Object.entries(data).map(([id, venta]) => ({
                id,
                ...venta
            })).reverse();

            const zonasUnicas = [...new Set(ventasList.map(v => v.zona).filter(z => z && z !== "Sin zona"))];
            setZonas(zonasUnicas);
            setVentas(ventasList);
        } else {
            setVentas([]);
        }
        setLoading(false);
    };

    useEffect(() => {
        cargarVentas();
        const ventasRef = ref(db, "ventas");
        const unsubscribe = onValue(ventasRef, () => cargarVentas());
        return () => unsubscribe();
    }, []);

    // Función corregida para eliminar venta y su ganancia asociada
    const eliminarVenta = async (venta) => {
        if (window.confirm(`¿Eliminar la venta de ${venta.cliente} por $${(venta.total || 0).toLocaleString()}?`)) {
            try {
                // 1. Eliminar la venta
                const ventaRef = ref(db, `ventas/${venta.id}`);
                await remove(ventaRef);

                // 2. Buscar y eliminar la ganancia asociada en el historial
                const gananciasRef = ref(db, "ganancias/historial");
                const snapshot = await get(gananciasRef);

                if (snapshot.exists()) {
                    const data = snapshot.val();
                    let encontrado = false;

                    for (const [key, value] of Object.entries(data)) {
                        // Comparar por cliente y fecha (aproximadamente)
                        const fechaGanancia = new Date(value.fechaGanancia);
                        const fechaVenta = new Date(venta.fecha);

                        // Comparar por cliente y misma fecha
                        if (value.cliente === venta.cliente &&
                            fechaGanancia.toLocaleDateString() === fechaVenta.toLocaleDateString()) {
                            await remove(ref(db, `ganancias/historial/${key}`));
                            encontrado = true;
                            console.log(`Ganancia eliminada: ${key}`);
                            break;
                        }
                    }

                    if (!encontrado) {
                        console.log("No se encontró la ganancia asociada para eliminar");
                    }
                }

                // 3. Actualizar el stock de los productos
                if (venta.productos && Array.isArray(venta.productos)) {
                    for (const producto of venta.productos) {
                        const productoRef = ref(db, `productos/${producto.id}`);
                        const productoSnapshot = await get(productoRef);
                        if (productoSnapshot.exists()) {
                            const productoData = productoSnapshot.val();
                            const nuevoStock = (productoData.stock || 0) + producto.cantidad;
                            await update(productoRef, { stock: nuevoStock });
                        }
                    }
                }

                setSnackbar({
                    open: true,
                    message: 'Venta y ganancia eliminadas correctamente',
                    severity: 'success'
                });

                // Recargar datos
                await cargarVentas();
                if (onRefresh) onRefresh();

            } catch (error) {
                console.error("Error al eliminar venta:", error);
                setSnackbar({
                    open: true,
                    message: 'Error al eliminar la venta',
                    severity: 'error'
                });
            }
        }
    };

    const abrirEditor = (venta) => {
        setEditandoVenta(venta);
        setVentaEdit({
            cliente: venta.cliente || '',
            zona: venta.zona || '',
            total: venta.total || 0,
            costoTotal: venta.costoTotal || 0,
            gananciaTotal: venta.gananciaTotal || 0,
            fecha: venta.fecha || new Date().toISOString()
        });
        setDialogOpen(true);
    };

    const guardarEdicion = async () => {
        if (!ventaEdit.cliente.trim()) {
            alert('El nombre del cliente es obligatorio');
            return;
        }

        try {
            const ventaRef = ref(db, `ventas/${editandoVenta.id}`);

            // Calcular nueva ganancia si cambió el total
            const nuevaGananciaTotal = ventaEdit.total - ventaEdit.costoTotal;

            const ventaActualizada = {
                ...editandoVenta,
                cliente: ventaEdit.cliente,
                zona: ventaEdit.zona || "Sin zona",
                total: ventaEdit.total,
                costoTotal: ventaEdit.costoTotal,
                gananciaTotal: nuevaGananciaTotal,
                fecha: ventaEdit.fecha
            };

            await update(ventaRef, ventaActualizada);

            // Actualizar también en ganancias/historial
            const gananciasRef = ref(db, "ganancias/historial");
            const snapshot = await get(gananciasRef);
            if (snapshot.exists()) {
                const data = snapshot.val();
                for (const [key, value] of Object.entries(data)) {
                    const fechaGanancia = new Date(value.fechaGanancia);
                    const fechaVenta = new Date(editandoVenta.fecha);
                    if (value.cliente === editandoVenta.cliente &&
                        fechaGanancia.toLocaleDateString() === fechaVenta.toLocaleDateString()) {
                        await update(ref(db, `ganancias/historial/${key}`), {
                            cliente: ventaEdit.cliente,
                            zona: ventaEdit.zona || "Sin zona",
                            total: nuevaGananciaTotal,
                            fechaGanancia: ventaEdit.fecha
                        });
                        break;
                    }
                }
            }

            setDialogOpen(false);
            setEditandoVenta(null);
            await cargarVentas();
            if (onRefresh) onRefresh();
            setSnackbar({ open: true, message: 'Venta actualizada correctamente', severity: 'success' });
        } catch (error) {
            console.error('Error al actualizar:', error);
            setSnackbar({ open: true, message: 'Error al actualizar la venta', severity: 'error' });
        }
    };

    const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

    const ventasFiltradas = ventas.filter(venta => {
        if (filtroCliente && !venta.cliente?.toLowerCase().includes(filtroCliente.toLowerCase())) return false;
        if (filtroZona && venta.zona !== filtroZona) return false;
        if (filtroFecha) {
            const fechaVenta = new Date(venta.fecha).toLocaleDateString();
            const fechaFiltro = new Date(filtroFecha).toLocaleDateString();
            if (fechaVenta !== fechaFiltro) return false;
        }
        return true;
    });

    const totalFiltrado = ventasFiltradas.reduce((sum, v) => sum + (v.gananciaTotal || 0), 0);
    const totalVentasFiltrado = ventasFiltradas.reduce((sum, v) => sum + (v.total || 0), 0);

    const TarjetaVenta = ({ venta, index }) => {
        const [open, setOpen] = useState(false);

        return (
            <Card sx={{ mb: 1.5 }}>
                <CardContent sx={{ p: 1.5, '&:last-child': { pb: 1.5 } }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <Chip label={`#${index + 1}`} size="small" color="primary" variant="outlined" />
                            <Typography variant="body2" fontWeight="bold">{venta.cliente}</Typography>
                        </Box>
                        <Box>
                            <Tooltip title="Ver detalles">
                                <IconButton size="small" onClick={() => setOpen(!open)}>
                                    {open ? <KeyboardArrowUpIcon /> : <KeyboardArrowDownIcon />}
                                </IconButton>
                            </Tooltip>
                            <Tooltip title="Editar">
                                <IconButton size="small" color="primary" onClick={() => abrirEditor(venta)}>
                                    <EditIcon fontSize="small" />
                                </IconButton>
                            </Tooltip>
                            <Tooltip title="Eliminar">
                                <IconButton size="small" color="error" onClick={() => eliminarVenta(venta)}>
                                    <DeleteIcon fontSize="small" />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    </Box>

                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                        <Typography variant="caption" color="text.secondary">Fecha:</Typography>
                        <Typography variant="caption">{new Date(venta.fecha).toLocaleDateString()}</Typography>
                    </Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                        <Typography variant="caption" color="text.secondary">Zona:</Typography>
                        <Chip label={venta.zona || "Sin zona"} size="small" variant="outlined" sx={{ height: 20, fontSize: '0.7rem' }} />
                    </Box>
                    <Divider sx={{ my: 1 }} />
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Typography variant="body2" color="text.secondary">Total venta:</Typography>
                        <Typography variant="body2" fontWeight="bold">${(venta.total || 0).toLocaleString()}</Typography>
                    </Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Typography variant="body2" color="text.secondary">Ganancia:</Typography>
                        <Typography variant="body2" fontWeight="bold" color="#4caf50">+${(venta.gananciaTotal || 0).toLocaleString()}</Typography>
                    </Box>

                    <Collapse in={open} timeout="auto" unmountOnExit>
                        <Box sx={{ mt: 2 }}>
                            <Typography variant="subtitle2" gutterBottom>Productos:</Typography>
                            {venta.productos?.map((prod, idx) => (
                                <Paper key={idx} sx={{ p: 1, mb: 1, backgroundColor: '#f5f5f5' }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Typography variant="body2">{prod.nombre}</Typography>
                                        <Typography variant="body2">x{prod.cantidad}</Typography>
                                    </Box>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                        <Typography variant="caption">${prod.precioVenta.toLocaleString()} c/u</Typography>
                                        <Typography variant="caption" color="#4caf50">+${prod.ganancia.toLocaleString()}</Typography>
                                    </Box>
                                </Paper>
                            ))}
                            <Box sx={{ mt: 1, pt: 1, borderTop: '1px solid #eee' }}>
                                <Typography variant="caption" display="block">Costo total: ${(venta.costoTotal || 0).toLocaleString()}</Typography>
                            </Box>
                        </Box>
                    </Collapse>
                </CardContent>
            </Card>
        );
    };

    return (
        <>
            <Box sx={{ mt: 2, px: isMobile ? 1 : 2 }}>
                <Paper sx={{ p: isMobile ? 1.5 : 2, mb: 2, backgroundColor: '#f3e5f5' }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2, flexWrap: 'wrap', gap: 1 }}>
                        <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1, fontSize: isMobile ? '1.2rem' : '1.5rem' }}>
                            <ReceiptIcon color="secondary" /> Historial de Ventas
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                            <Button size="small" startIcon={<FilterListIcon />} onClick={() => setMostrarFiltros(!mostrarFiltros)}>
                                Filtros
                            </Button>
                            <Button size="small" startIcon={<RefreshIcon />} onClick={cargarVentas}>
                                Actualizar
                            </Button>
                        </Box>
                    </Box>

                    {(mostrarFiltros || !isMobile) && (
                        <Stack direction={isMobile ? 'column' : 'row'} spacing={1.5} sx={{ mb: 2 }}>
                            <TextField
                                label="Buscar cliente"
                                value={filtroCliente}
                                onChange={(e) => setFiltroCliente(e.target.value)}
                                size="small"
                                placeholder="Nombre..."
                                fullWidth={isMobile}
                            />
                            <FormControl size="small" fullWidth={isMobile}>
                                <InputLabel>Zona</InputLabel>
                                <Select value={filtroZona} onChange={(e) => setFiltroZona(e.target.value)} label="Zona">
                                    <MenuItem value="">Todas</MenuItem>
                                    {zonas.map(z => <MenuItem key={z} value={z}>{z}</MenuItem>)}
                                </Select>
                            </FormControl>
                            <TextField
                                label="Fecha"
                                type="date"
                                value={filtroFecha}
                                onChange={(e) => setFiltroFecha(e.target.value)}
                                size="small"
                                InputLabelProps={{ shrink: true }}
                                fullWidth={isMobile}
                            />
                            <Button size="small" onClick={() => {
                                setFiltroCliente('');
                                setFiltroZona('');
                                setFiltroFecha('');
                            }}>
                                Limpiar
                            </Button>
                        </Stack>
                    )}

                    {loading ? (
                        <Typography textAlign="center" py={4}>Cargando ventas...</Typography>
                    ) : ventasFiltradas.length === 0 ? (
                        <Paper sx={{ p: 4, textAlign: 'center', backgroundColor: '#fafafa' }}>
                            <ReceiptIcon sx={{ fontSize: 48, color: '#ccc', mb: 2 }} />
                            <Typography variant="h6" color="text.secondary">No hay ventas registradas</Typography>
                        </Paper>
                    ) : (
                        <>
                            {isMobile ? (
                                <Box sx={{ maxHeight: 500, overflow: 'auto' }}>
                                    {ventasFiltradas.map((venta, idx) => (
                                        <TarjetaVenta key={venta.id} venta={venta} index={idx} />
                                    ))}
                                </Box>
                            ) : (
                                <TableContainer component={Paper} sx={{ maxHeight: 500 }}>
                                    <Table stickyHeader size="small">
                                        <TableHead>
                                            <TableRow>
                                                <TableCell>Cliente</TableCell>
                                                <TableCell>Fecha</TableCell>
                                                <TableCell>Zona</TableCell>
                                                <TableCell align="right">Total</TableCell>
                                                <TableCell align="right">Ganancia</TableCell>
                                                <TableCell align="center">Acciones</TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            {ventasFiltradas.map((venta) => (
                                                <TableRow key={venta.id}>
                                                    <TableCell>{venta.cliente}</TableCell>
                                                    <TableCell>{new Date(venta.fecha).toLocaleDateString()}</TableCell>
                                                    <TableCell>{venta.zona}</TableCell>
                                                    <TableCell align="right">${(venta.total || 0).toLocaleString()}</TableCell>
                                                    <TableCell align="right" sx={{ color: '#4caf50' }}>+${(venta.gananciaTotal || 0).toLocaleString()}</TableCell>
                                                    <TableCell align="center">
                                                        <Tooltip title="Editar">
                                                            <IconButton size="small" color="primary" onClick={() => abrirEditor(venta)}>
                                                                <EditIcon fontSize="small" />
                                                            </IconButton>
                                                        </Tooltip>
                                                        <Tooltip title="Eliminar">
                                                            <IconButton size="small" color="error" onClick={() => eliminarVenta(venta)}>
                                                                <DeleteIcon fontSize="small" />
                                                            </IconButton>
                                                        </Tooltip>
                                                    </TableCell>
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                    </Table>
                                </TableContainer>
                            )}

                            <Paper sx={{ mt: 2, p: 1.5, backgroundColor: '#e8f5e9', borderRadius: 2 }}>
                                <Stack direction={isMobile ? 'column' : 'row'} spacing={1} justifyContent="space-between">
                                    <Typography variant="body2">
                                        Total ventas: <strong>${totalVentasFiltrado.toLocaleString()}</strong>
                                    </Typography>
                                    <Typography variant="body2">
                                        Total ganancia: <strong style={{ color: '#4caf50' }}>+${totalFiltrado.toLocaleString()}</strong>
                                    </Typography>
                                </Stack>
                            </Paper>
                        </>
                    )}
                </Paper>
            </Box>

            {/* Snackbar para notificaciones */}
            <Snackbar
                open={snackbar.open}
                autoHideDuration={3000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert severity={snackbar.severity} sx={{ fontSize: isMobile ? '0.8rem' : '0.9rem' }}>
                    {snackbar.message}
                </Alert>
            </Snackbar>

            {/* Diálogo de edición */}
            <Dialog
                open={dialogOpen}
                onClose={() => setDialogOpen(false)}
                maxWidth="sm"
                fullWidth
                fullScreen={isMobile}
            >
                <DialogTitle>
                    Editar Venta
                    <IconButton
                        aria-label="close"
                        onClick={() => setDialogOpen(false)}
                        sx={{ position: 'absolute', right: 8, top: 8 }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent dividers>
                    <Stack spacing={2} sx={{ mt: 1 }}>
                        <TextField
                            label="Cliente"
                            value={ventaEdit.cliente || ''}
                            onChange={(e) => setVentaEdit({ ...ventaEdit, cliente: e.target.value })}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Zona"
                            value={ventaEdit.zona || ''}
                            onChange={(e) => setVentaEdit({ ...ventaEdit, zona: e.target.value })}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Total de la venta"
                            type="number"
                            value={ventaEdit.total || 0}
                            onChange={(e) => {
                                const nuevoTotal = parseFloat(e.target.value) || 0;
                                setVentaEdit({
                                    ...ventaEdit,
                                    total: nuevoTotal,
                                    gananciaTotal: nuevoTotal - ventaEdit.costoTotal
                                });
                            }}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Costo total"
                            type="number"
                            value={ventaEdit.costoTotal || 0}
                            onChange={(e) => {
                                const nuevoCosto = parseFloat(e.target.value) || 0;
                                setVentaEdit({
                                    ...ventaEdit,
                                    costoTotal: nuevoCosto,
                                    gananciaTotal: ventaEdit.total - nuevoCosto
                                });
                            }}
                            fullWidth
                            size="small"
                        />
                        <TextField
                            label="Ganancia"
                            type="number"
                            value={ventaEdit.gananciaTotal || 0}
                            InputProps={{ readOnly: true }}
                            fullWidth
                            size="small"
                            sx={{ '& .MuiInputBase-input': { color: '#4caf50', fontWeight: 'bold' } }}
                        />
                        <TextField
                            label="Fecha"
                            type="date"
                            value={ventaEdit.fecha ? new Date(ventaEdit.fecha).toISOString().split('T')[0] : ''}
                            onChange={(e) => setVentaEdit({ ...ventaEdit, fecha: new Date(e.target.value).toISOString() })}
                            fullWidth
                            size="small"
                            InputLabelProps={{ shrink: true }}
                        />
                    </Stack>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setDialogOpen(false)} color="inherit">
                        Cancelar
                    </Button>
                    <Button onClick={guardarEdicion} color="primary" variant="contained" startIcon={<SaveIcon />}>
                        Guardar Cambios
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default HistorialVentas;