// src/components/Ganancias/GestorCobros.js
import React, { useState, useEffect } from 'react';
import {
    Box, Typography, Button, Modal, TextField, Stack, Paper,
    List, ListItem, ListItemText, ListItemSecondaryAction,
    IconButton, Chip, Alert, Snackbar, Divider, Badge,
    useMediaQuery, useTheme, Card, CardContent, FormControl,
    InputLabel, Select, MenuItem, InputAdornment
} from '@mui/material';
import { ref, get, push, remove, update } from "firebase/database";
import { db } from "./firebaseConfig";
import CloseIcon from '@mui/icons-material/Close';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import DeleteIcon from '@mui/icons-material/Delete';
import NotificationsActiveIcon from '@mui/icons-material/NotificationsActive';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import PersonIcon from '@mui/icons-material/Person';
import AddIcon from '@mui/icons-material/Add';
import WarningIcon from '@mui/icons-material/Warning';
import Autocomplete from '@mui/material/Autocomplete';

const GestorCobros = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const [open, setOpen] = useState(false);
    const [cobros, setCobros] = useState([]);
    const [cobrosPendientesHoy, setCobrosPendientesHoy] = useState([]);
    const [cobrosVencidos, setCobrosVencidos] = useState([]);
    const [nuevoCobro, setNuevoCobro] = useState({
        cliente: '',
        monto: '',
        fechaCobro: '',
        descripcion: '',
        zona: ''
    });
    const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
    const [clientes, setClientes] = useState([]);
    const [notificacionVencidosMostrada, setNotificacionVencidosMostrada] = useState(false);

    useEffect(() => {
        cargarCobros();
        cargarClientes();
    }, []);

    useEffect(() => {
        // Cada vez que cambian los cobros, verificar todos
        if (cobros.length > 0) {
            verificarTodosLosCobros();
        }
    }, [cobros]);

    const cargarClientes = async () => {
        const clientesRef = ref(db, "clientes");
        const snapshot = await get(clientesRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const clientesList = Object.values(data).map(c => c.nombre);
            setClientes(clientesList);
        }
    };

    const cargarCobros = async () => {
        const cobrosRef = ref(db, "cobros");
        const snapshot = await get(cobrosRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const cobrosList = Object.entries(data).map(([id, cobro]) => ({
                id,
                ...cobro
            }));
            // Ordenar por fecha más cercana primero
            cobrosList.sort((a, b) => new Date(a.fechaCobro) - new Date(b.fechaCobro));
            setCobros(cobrosList);
        } else {
            setCobros([]);
        }
    };

    // Formatear lista de clientes deudores para mostrar
    const formatearListaDeudores = (cobrosLista, limite = 3) => {
        if (cobrosLista.length === 0) return '';

        // Si son pocos, mostrar todos
        if (cobrosLista.length <= limite) {
            return cobrosLista.map(c => `${c.cliente} ($${c.monto.toLocaleString()})`).join(', ');
        }

        // Si son muchos, mostrar los primeros y un resumen
        const primeros = cobrosLista.slice(0, limite).map(c => `${c.cliente} ($${c.monto.toLocaleString()})`).join(', ');
        const restantes = cobrosLista.length - limite;
        return `${primeros} y ${restantes} más`;
    };

    // Formatear lista detallada con montos
    const formatearListaDetallada = (cobrosLista) => {
        return cobrosLista.map(c => `• ${c.cliente}: $${c.monto.toLocaleString()}`).join('\n');
    };

    const verificarTodosLosCobros = () => {
        const hoy = new Date();
        hoy.setHours(0, 0, 0, 0);

        // Separar cobros pendientes
        const pendientes = cobros.filter(c => c.estado !== 'cobrado');

        // Cobros para hoy
        const paraHoy = pendientes.filter(cobro => {
            const fechaCobro = new Date(cobro.fechaCobro);
            fechaCobro.setHours(0, 0, 0, 0);
            return fechaCobro.getTime() === hoy.getTime();
        });

        // Cobros vencidos (fecha anterior a hoy)
        const vencidos = pendientes.filter(cobro => {
            const fechaCobro = new Date(cobro.fechaCobro);
            fechaCobro.setHours(0, 0, 0, 0);
            return fechaCobro.getTime() < hoy.getTime();
        });

        setCobrosPendientesHoy(paraHoy);
        setCobrosVencidos(vencidos);

        // Mostrar notificaciones si es necesario
        mostrarNotificacionesSiCorresponde(paraHoy, vencidos);

        // Mostrar snackbar si hay cobros pendientes hoy
        if (paraHoy.length > 0 && !open) {
            const listaClientes = formatearListaDeudores(paraHoy, 2);
            const totalHoy = paraHoy.reduce((sum, c) => sum + c.monto, 0);

            setSnackbar({
                open: true,
                message: `⚠️ Cobros para hoy (${paraHoy.length}): ${listaClientes}\nTotal: $${totalHoy.toLocaleString()}`,
                severity: 'warning'
            });
        }

        // Mostrar snackbar si hay cobros vencidos (con lista de clientes)
        if (vencidos.length > 0 && !open && !notificacionVencidosMostrada) {
            const totalVencido = vencidos.reduce((sum, c) => sum + c.monto, 0);
            const listaClientes = formatearListaDeudores(vencidos, 3);

            setSnackbar({
                open: true,
                message: `⚠️⚠️ COBROS VENCIDOS (${vencidos.length}):\n${listaClientes}\nTotal vencido: $${totalVencido.toLocaleString()}`,
                severity: 'error'
            });

            setNotificacionVencidosMostrada(true);
        }
    };

    const mostrarNotificacionesSiCorresponde = (paraHoy, vencidos) => {
        // Verificar permisos de manera segura
        if (!('Notification' in window)) return;
        if (Notification.permission !== 'granted') return;

        // Evitar múltiples notificaciones iguales
        const ahora = Date.now();
        const ultimaNotificacionVencidos = sessionStorage.getItem('ultimaNotificacionVencidos');
        const ultimaNotificacionHoy = sessionStorage.getItem('ultimaNotificacionHoy');

        // Notificación para cobros vencidos (con lista detallada)
        if (vencidos.length > 0) {
            const totalVencido = vencidos.reduce((sum, c) => sum + c.monto, 0);
            const listaDetallada = formatearListaDetallada(vencidos);

            // Mostrar solo cada 10 minutos para no spamear
            if (!ultimaNotificacionVencidos || (ahora - parseInt(ultimaNotificacionVencidos)) > 600000) {
                try {
                    const titulo = vencidos.length === 1
                        ? `⚠️⚠️ COBRO VENCIDO: ${vencidos[0].cliente} ⚠️⚠️`
                        : `⚠️⚠️ ${vencidos.length} COBROS VENCIDOS ⚠️⚠️`;

                    const cuerpo = vencidos.length <= 5
                        ? `${listaDetallada}\n\n💰 Total Adeudado: $${totalVencido.toLocaleString()}`
                        : `${listaDetallada}\n... y ${vencidos.length - 5} más\n\n💰 Total Adeudado: $${totalVencido.toLocaleString()}`;

                    if (window.mostrarNotificacionGlobal) {
                        window.mostrarNotificacionGlobal(titulo, cuerpo);
                    } else {
                        new Notification(titulo, {
                            body: cuerpo,
                            icon: '/favicon.ico',
                            vibrate: [300, 100, 300, 100, 300],
                            requireInteraction: true,
                            tag: 'cobros-vencidos'
                        });
                    }
                    sessionStorage.setItem('ultimaNotificacionVencidos', ahora.toString());
                } catch (error) {
                    console.error('Error al mostrar notificación:', error);
                }
            }
        }

        // Notificación para cobros de hoy (con lista de clientes)
        if (paraHoy.length > 0) {
            const totalHoy = paraHoy.reduce((sum, c) => sum + c.monto, 0);
            const listaDetallada = formatearListaDetallada(paraHoy);

            // Mostrar solo cada 3 horas para no spamear
            if (!ultimaNotificacionHoy || (ahora - parseInt(ultimaNotificacionHoy)) > 10800000) {
                try {
                    const titulo = paraHoy.length === 1
                        ? `💰 Recordatorio: Cobro pendiente - ${paraHoy[0].cliente}`
                        : `💰 Recordatorio: ${paraHoy.length} cobros pendientes hoy`;

                    const cuerpo = paraHoy.length <= 5
                        ? `${listaDetallada}\n\n💵 Total a cobrar: $${totalHoy.toLocaleString()}`
                        : `${listaDetallada}\n... y ${paraHoy.length - 5} más\n\n💵 Total a cobrar: $${totalHoy.toLocaleString()}`;

                    if (window.mostrarNotificacionGlobal) {
                        window.mostrarNotificacionGlobal(titulo, cuerpo);
                    } else {
                        new Notification(titulo, {
                            body: cuerpo,
                            icon: '/favicon.ico',
                            vibrate: [200, 100, 200],
                            requireInteraction: true,
                            tag: 'cobros-hoy'
                        });
                    }
                    sessionStorage.setItem('ultimaNotificacionHoy', ahora.toString());
                } catch (error) {
                    console.error('Error al mostrar notificación:', error);
                }
            }
        }
    };

    const agregarCobro = async () => {
        if (!nuevoCobro.cliente || !nuevoCobro.monto || !nuevoCobro.fechaCobro) {
            setSnackbar({ open: true, message: '⚠️ Completa todos los campos obligatorios', severity: 'error' });
            return;
        }

        const fechaCobro = new Date(nuevoCobro.fechaCobro);
        const hoy = new Date();
        hoy.setHours(0, 0, 0, 0);
        const esVencido = fechaCobro.getTime() < hoy.getTime();
        const esHoy = fechaCobro.getTime() === hoy.getTime();

        const cobroData = {
            cliente: nuevoCobro.cliente,
            monto: parseFloat(nuevoCobro.monto),
            fechaCobro: new Date(nuevoCobro.fechaCobro).toISOString(),
            descripcion: nuevoCobro.descripcion || '',
            zona: nuevoCobro.zona || '',
            estado: 'pendiente',
            fechaCreacion: new Date().toISOString()
        };

        try {
            await push(ref(db, "cobros"), cobroData);
            setNuevoCobro({ cliente: '', monto: '', fechaCobro: '', descripcion: '', zona: '' });
            await cargarCobros();

            // Mostrar mensaje específico si es vencido
            if (esVencido) {
                setSnackbar({
                    open: true,
                    message: `⚠️ ATENCIÓN: Cobro VENCIDO de ${nuevoCobro.cliente} por $${parseFloat(nuevoCobro.monto).toLocaleString()} (fecha: ${fechaCobro.toLocaleDateString()})`,
                    severity: 'error'
                });

                // Notificación inmediata para cobro vencido recién agregado
                if (Notification.permission === 'granted') {
                    new Notification('⚠️ Cobro Vencido Registrado', {
                        body: `${nuevoCobro.cliente} - $${parseFloat(nuevoCobro.monto).toLocaleString()} (Vencido el ${fechaCobro.toLocaleDateString()})`,
                        icon: '/favicon.ico',
                        vibrate: [300, 100, 300],
                        requireInteraction: true
                    });
                }
            } else if (esHoy) {
                setSnackbar({
                    open: true,
                    message: `📅 Cobro registrado para HOY: ${nuevoCobro.cliente} - $${parseFloat(nuevoCobro.monto).toLocaleString()}`,
                    severity: 'warning'
                });
            } else {
                setSnackbar({
                    open: true,
                    message: `✅ Cobro registrado: ${nuevoCobro.cliente} - $${parseFloat(nuevoCobro.monto).toLocaleString()}`,
                    severity: 'success'
                });
            }

        } catch (error) {
            console.error("Error al agregar cobro:", error);
            setSnackbar({ open: true, message: '❌ Error al registrar el cobro', severity: 'error' });
        }
    };


    const marcarCobrado = async (cobroId) => {
        try {
            const cobroRef = ref(db, `cobros/${cobroId}`);
            const cobroAActualizar = cobros.find(c => c.id === cobroId);

            await update(cobroRef, {
                estado: 'cobrado',
                fechaCobroRealizado: new Date().toISOString()
            });
            await cargarCobros();

            // Mostrar mensaje con el cliente específico
            setSnackbar({
                open: true,
                message: `✅ ¡Excelente! ${cobroAActualizar.cliente} pagó $${cobroAActualizar.monto.toLocaleString()}`,
                severity: 'success'
            });

            // Notificación opcional
            if (Notification.permission === 'granted') {
                new Notification('✅ Cobro Registrado', {
                    body: `${cobroAActualizar.cliente} pagó $${cobroAActualizar.monto.toLocaleString()}`,
                    icon: '/favicon.ico',
                    vibrate: [200, 100, 200]
                });
            }
        } catch (error) {
            console.error("Error al marcar cobro:", error);
            setSnackbar({ open: true, message: 'Error al actualizar el cobro', severity: 'error' });
        }
    };

    const eliminarCobro = async (cobroId) => {
        if (window.confirm('¿Eliminar este cobro?')) {
            try {
                await remove(ref(db, `cobros/${cobroId}`));
                await cargarCobros();
                setSnackbar({ open: true, message: 'Cobro eliminado', severity: 'success' });
            } catch (error) {
                console.error("Error al eliminar cobro:", error);
                setSnackbar({ open: true, message: 'Error al eliminar el cobro', severity: 'error' });
            }
        }
    };

    const formatearFecha = (fechaISO) => {
        const fecha = new Date(fechaISO);
        return fecha.toLocaleDateString('es-ES', {
            day: 'numeric',
            month: 'long',
            year: 'numeric'
        });
    };

    const getDiasRestantes = (fechaISO) => {
        const hoy = new Date();
        hoy.setHours(0, 0, 0, 0);
        const fechaCobro = new Date(fechaISO);
        fechaCobro.setHours(0, 0, 0, 0);
        const diffTime = fechaCobro - hoy;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        return diffDays;
    };

    // Contador total de pendientes (incluye vencidos)
    const totalPendientes = cobros.filter(c => c.estado !== 'cobrado').length;

    return (
        <>
            {/* Botón de cobros con badge */}
            <Button
                variant="contained"
                onClick={() => setOpen(true)}
                sx={{
                    background: cobrosVencidos.length > 0
                        ? 'linear-gradient(135deg, #f44336 0%, #d32f2f 100%)'
                        : 'linear-gradient(135deg, #ff9800 0%, #f57c00 100%)',
                    '&:hover': {
                        background: cobrosVencidos.length > 0
                            ? 'linear-gradient(135deg, #d32f2f 0%, #c62828 100%)'
                            : 'linear-gradient(135deg, #f57c00 0%, #e65100 100%)'
                    }
                }}
                startIcon={
                    <Badge badgeContent={totalPendientes} color="error">
                        <AttachMoneyIcon />
                    </Badge>
                }
            >
                {cobrosVencidos.length > 0 ? `❗ ${cobrosVencidos.length} Vencidos ❗` : 'Deudas'}
            </Button>

            {/* Modal principal */}
            <Modal
                open={open}
                onClose={() => setOpen(false)}
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    p: 2
                }}
            >
                <Paper sx={{
                    width: '100%',
                    maxWidth: 800,
                    maxHeight: '90vh',
                    overflow: 'auto',
                    p: { xs: 2, sm: 3 },
                    borderRadius: 3
                }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                        <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <AttachMoneyIcon sx={{ color: '#ff9800' }} />
                            Gestión de Cobros
                        </Typography>
                        <IconButton onClick={() => setOpen(false)}>
                            <CloseIcon />
                        </IconButton>
                    </Box>

                    {/* Alerta de cobros vencidos (más importante) */}
                    {cobrosVencidos.length > 0 && (
                        <Alert severity="error" sx={{ mb: 2 }} icon={<WarningIcon />}>
                            <Typography variant="body2" fontWeight="bold">
                                ⚠️⚠️ ATENCIÓN: Tienes {cobrosVencidos.length} cobro(s) VENCIDO(S) ⚠️⚠️
                            </Typography>
                            <Typography variant="body2">
                                Total vencido: ${cobrosVencidos.reduce((sum, c) => sum + c.monto, 0).toLocaleString()}
                            </Typography>
                        </Alert>
                    )}

                    {/* Alerta de cobros pendientes hoy */}
                    {cobrosPendientesHoy.length > 0 && (
                        <Alert severity="warning" sx={{ mb: 2 }} icon={<NotificationsActiveIcon />}>
                            <Typography variant="body2">
                                ⚠️ Tienes <strong>{cobrosPendientesHoy.length}</strong> cobro(s) pendiente(s) para hoy
                            </Typography>
                        </Alert>
                    )}

                    {/* Formulario para agregar nuevo cobro */}
                    <Paper sx={{ p: 2, mb: 3, backgroundColor: '#fff3e0' }}>
                        <Typography variant="subtitle1" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <AddIcon /> Nuevo Cobro Pendiente
                        </Typography>
                        <Stack spacing={2}>
                            <Autocomplete
                                freeSolo
                                options={clientes}
                                value={nuevoCobro.cliente}
                                onInputChange={(event, newValue) => setNuevoCobro({ ...nuevoCobro, cliente: newValue || '' })}
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        label="Cliente *"
                                        size="small"
                                        InputProps={{
                                            ...params.InputProps,
                                            startAdornment: (
                                                <InputAdornment position="start">
                                                    <PersonIcon sx={{ color: 'gray', fontSize: 20 }} />
                                                </InputAdornment>
                                            ),
                                        }}
                                    />
                                )}
                            />
                            <Stack direction={isMobile ? 'column' : 'row'} spacing={2}>
                                <TextField
                                    label="Monto *"
                                    type="number"
                                    value={nuevoCobro.monto}
                                    onChange={(e) => setNuevoCobro({ ...nuevoCobro, monto: e.target.value })}
                                    size="small"
                                    fullWidth
                                    InputProps={{
                                        startAdornment: <InputAdornment position="start">$</InputAdornment>,
                                    }}
                                />
                                <TextField
                                    label="Fecha de cobro *"
                                    type="date"
                                    value={nuevoCobro.fechaCobro}
                                    onChange={(e) => setNuevoCobro({ ...nuevoCobro, fechaCobro: e.target.value })}
                                    size="small"
                                    fullWidth
                                    InputLabelProps={{ shrink: true }}
                                    InputProps={{
                                        startAdornment: (
                                            <InputAdornment position="start">
                                                <CalendarTodayIcon sx={{ fontSize: 20 }} />
                                            </InputAdornment>
                                        ),
                                    }}
                                />
                            </Stack>
                            <Stack direction={isMobile ? 'column' : 'row'} spacing={2}>
                                <TextField
                                    label="Zona"
                                    value={nuevoCobro.zona}
                                    onChange={(e) => setNuevoCobro({ ...nuevoCobro, zona: e.target.value })}
                                    size="small"
                                    fullWidth
                                    placeholder="Ej: Centro, Norte"
                                />
                                <TextField
                                    label="Descripción (opcional)"
                                    value={nuevoCobro.descripcion}
                                    onChange={(e) => setNuevoCobro({ ...nuevoCobro, descripcion: e.target.value })}
                                    size="small"
                                    fullWidth
                                />
                            </Stack>
                            <Button
                                variant="contained"
                                onClick={agregarCobro}
                                startIcon={<AddIcon />}
                                sx={{ backgroundColor: '#ff9800', '&:hover': { backgroundColor: '#f57c00' } }}
                            >
                                Agregar Cobro
                            </Button>
                        </Stack>
                    </Paper>

                    {/* Lista de cobros pendientes (mostrar vencidos primero) */}
                    <Typography variant="subtitle1" gutterBottom sx={{ mt: 2 }}>
                        📋 Cobros Pendientes {cobrosVencidos.length > 0 && `(${cobrosVencidos.length} vencidos)`}
                    </Typography>
                    {cobros.filter(c => c.estado !== 'cobrado').length === 0 ? (
                        <Paper sx={{ p: 4, textAlign: 'center' }}>
                            <Typography color="text.secondary">No hay cobros pendientes</Typography>
                        </Paper>
                    ) : (
                        <List>
                            {/* Primero mostrar los vencidos */}
                            {cobrosVencidos.map((cobro) => {
                                const diasVencido = Math.abs(getDiasRestantes(cobro.fechaCobro));
                                return (
                                    <Paper key={cobro.id} sx={{ mb: 1, overflow: 'hidden', backgroundColor: '#ffebee' }}>
                                        <ListItem sx={{
                                            flexDirection: isMobile ? 'column' : 'row',
                                            alignItems: isMobile ? 'stretch' : 'center'
                                        }}>
                                            <Box sx={{ flex: 1 }}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                                    <WarningIcon fontSize="small" sx={{ color: '#f44336' }} />
                                                    <Typography variant="body1" fontWeight="bold" sx={{ color: '#c62828' }}>
                                                        {cobro.cliente}
                                                    </Typography>
                                                    {cobro.zona && (
                                                        <Chip label={cobro.zona} size="small" variant="outlined" />
                                                    )}
                                                </Box>
                                                <Typography variant="h6" color="#f44336" fontWeight="bold">
                                                    ${cobro.monto.toLocaleString()}
                                                </Typography>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                                                    <CalendarTodayIcon fontSize="small" sx={{ color: '#666' }} />
                                                    <Typography variant="body2" color="error" fontWeight="bold">
                                                        VENCIDO - {formatearFecha(cobro.fechaCobro)}
                                                    </Typography>
                                                    <Chip label={`Vencido hace ${diasVencido} días`} size="small" color="error" />
                                                </Box>
                                                {cobro.descripcion && (
                                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                                        📝 {cobro.descripcion}
                                                    </Typography>
                                                )}
                                            </Box>
                                            <Box sx={{
                                                display: 'flex',
                                                gap: 1,
                                                mt: isMobile ? 2 : 0,
                                                justifyContent: isMobile ? 'flex-end' : 'flex-start'
                                            }}>
                                                <Button
                                                    size="small"
                                                    variant="contained"
                                                    color="success"
                                                    onClick={() => marcarCobrado(cobro.id)}
                                                    startIcon={<CheckCircleIcon />}
                                                >
                                                    Cobrado
                                                </Button>
                                                <IconButton
                                                    size="small"
                                                    color="error"
                                                    onClick={() => eliminarCobro(cobro.id)}
                                                >
                                                    <DeleteIcon />
                                                </IconButton>
                                            </Box>
                                        </ListItem>
                                    </Paper>
                                );
                            })}

                            {/* Luego mostrar los pendientes no vencidos */}
                            {cobros.filter(c => c.estado !== 'cobrado' && getDiasRestantes(c.fechaCobro) >= 0).map((cobro) => {
                                const diasRestantes = getDiasRestantes(cobro.fechaCobro);
                                const esHoy = diasRestantes === 0;

                                return (
                                    <Paper key={cobro.id} sx={{ mb: 1, overflow: 'hidden' }}>
                                        <ListItem sx={{
                                            backgroundColor: esHoy ? '#fff3e0' : 'white',
                                            flexDirection: isMobile ? 'column' : 'row',
                                            alignItems: isMobile ? 'stretch' : 'center'
                                        }}>
                                            <Box sx={{ flex: 1 }}>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                                                    <PersonIcon fontSize="small" sx={{ color: '#666' }} />
                                                    <Typography variant="body1" fontWeight="bold">
                                                        {cobro.cliente}
                                                    </Typography>
                                                    {cobro.zona && (
                                                        <Chip label={cobro.zona} size="small" variant="outlined" />
                                                    )}
                                                </Box>
                                                <Typography variant="h6" color="#ff9800" fontWeight="bold">
                                                    ${cobro.monto.toLocaleString()}
                                                </Typography>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                                                    <CalendarTodayIcon fontSize="small" sx={{ color: '#666' }} />
                                                    <Typography variant="body2" color="text.secondary">
                                                        {formatearFecha(cobro.fechaCobro)}
                                                    </Typography>
                                                    {esHoy && (
                                                        <Chip label="HOY" size="small" color="warning" />
                                                    )}
                                                    {!esHoy && diasRestantes <= 3 && (
                                                        <Chip label={`En ${diasRestantes} días`} size="small" color="info" />
                                                    )}
                                                </Box>
                                                {cobro.descripcion && (
                                                    <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                                                        📝 {cobro.descripcion}
                                                    </Typography>
                                                )}
                                            </Box>
                                            <Box sx={{
                                                display: 'flex',
                                                gap: 1,
                                                mt: isMobile ? 2 : 0,
                                                justifyContent: isMobile ? 'flex-end' : 'flex-start'
                                            }}>
                                                <Button
                                                    size="small"
                                                    variant="contained"
                                                    color="success"
                                                    onClick={() => marcarCobrado(cobro.id)}
                                                    startIcon={<CheckCircleIcon />}
                                                >
                                                    Cobrado
                                                </Button>
                                                <IconButton
                                                    size="small"
                                                    color="error"
                                                    onClick={() => eliminarCobro(cobro.id)}
                                                >
                                                    <DeleteIcon />
                                                </IconButton>
                                            </Box>
                                        </ListItem>
                                    </Paper>
                                );
                            })}
                        </List>
                    )}

                    {/* Historial de cobros realizados */}
                    {cobros.filter(c => c.estado === 'cobrado').length > 0 && (
                        <>
                            <Typography variant="subtitle1" gutterBottom sx={{ mt: 3 }}>
                                ✅ Cobros Realizados
                            </Typography>
                            <List>
                                {cobros.filter(c => c.estado === 'cobrado').map((cobro) => (
                                    <Paper key={cobro.id} sx={{ mb: 1, backgroundColor: '#e8f5e9' }}>
                                        <ListItem>
                                            <ListItemText
                                                primary={
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                        <PersonIcon fontSize="small" />
                                                        <Typography variant="body2" fontWeight="bold">
                                                            {cobro.cliente}
                                                        </Typography>
                                                        <Chip label={`$${cobro.monto.toLocaleString()}`} size="small" color="success" />
                                                    </Box>
                                                }
                                                secondary={`Cobrado el: ${formatearFecha(cobro.fechaCobroRealizado || cobro.fechaCobro)}`}
                                            />
                                        </ListItem>
                                    </Paper>
                                ))}
                            </List>
                        </>
                    )}
                </Paper>
            </Modal>



            <Snackbar
                open={snackbar.open}
                autoHideDuration={6000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert
                    severity={snackbar.severity}
                    sx={{
                        fontSize: isMobile ? '0.8rem' : '0.9rem',
                        backgroundColor: '#d32f2f',
                        color: '#ffffff',
                        '& .MuiAlert-icon': {
                            color: '#ffffff'
                        },
                        '& .MuiAlert-action': {
                            color: '#ffffff'
                        },
                        '& .MuiButtonBase-root': {
                            color: '#ffffff'
                        }
                    }}
                >
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </>
    );
};

export default GestorCobros;