// src/components/Ganancias/GestorProductos.js
import React, { useState, useEffect } from 'react';
import {
    Box, Typography, TextField, Button, Paper, Table, TableBody, TableCell,
    TableContainer, TableHead, TableRow, IconButton, Modal, Fade, Backdrop,
    InputAdornment, Chip, useMediaQuery, useTheme, Stack, Card, CardContent
} from '@mui/material';
import { ref, get, push, remove, update } from "firebase/database";
import { db } from "./firebaseConfig";
import AddIcon from '@mui/icons-material/Add';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import InventoryIcon from '@mui/icons-material/Inventory';
import SearchIcon from '@mui/icons-material/Search';

const GestorProductos = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

    const [productos, setProductos] = useState([]);
    const [productosFiltrados, setProductosFiltrados] = useState([]);
    const [busqueda, setBusqueda] = useState('');
    const [openModal, setOpenModal] = useState(false);
    const [editando, setEditando] = useState(null);
    const [nombre, setNombre] = useState('');
    const [precioCosto, setPrecioCosto] = useState('');
    const [precioVenta, setPrecioVenta] = useState('');

    useEffect(() => {
        cargarProductos();
    }, []);

    useEffect(() => {
        const filtrados = productos.filter(p =>
            p.nombre.toLowerCase().includes(busqueda.toLowerCase())
        );
        setProductosFiltrados(filtrados);
    }, [busqueda, productos]);

    const cargarProductos = async () => {
        const productosRef = ref(db, "productos");
        const snapshot = await get(productosRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const productosList = Object.entries(data).map(([id, producto]) => ({
                id,
                ...producto
            }));
            setProductos(productosList);
        }
    };

    const guardarProducto = async () => {
        if (!nombre || !precioCosto || !precioVenta) {
            alert("Completa todos los campos");
            return;
        }

        const productoData = {
            nombre,
            precioCosto: parseFloat(precioCosto),
            precioVenta: parseFloat(precioVenta),
            ganancia: parseFloat(precioVenta) - parseFloat(precioCosto),
            fechaCreacion: new Date().toISOString()
        };

        if (editando) {
            await update(ref(db, `productos/${editando}`), productoData);
        } else {
            await push(ref(db, "productos"), productoData);
        }

        cerrarModal();
        cargarProductos();
    };

    const eliminarProducto = async (id) => {
        if (window.confirm("¿Eliminar este producto?")) {
            await remove(ref(db, `productos/${id}`));
            cargarProductos();
        }
    };

    const TarjetaProducto = ({ producto }) => (
        <Card sx={{ mb: 1 }}>
            <CardContent sx={{ p: 1.5, '&:last-child': { pb: 1.5 } }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Typography variant="body2" fontWeight="bold">{producto.nombre}</Typography>
                    <Box>
                        <IconButton size="small" color="primary" onClick={() => abrirModalEditar(producto)}>
                            <EditIcon fontSize="small" />
                        </IconButton>
                        <IconButton size="small" color="error" onClick={() => eliminarProducto(producto.id)}>
                            <DeleteIcon fontSize="small" />
                        </IconButton>
                    </Box>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 1 }}>
                    <Typography variant="caption" color="text.secondary">Costo:</Typography>
                    <Typography variant="caption">${producto.precioCosto.toLocaleString()}</Typography>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Typography variant="caption" color="text.secondary">Venta:</Typography>
                    <Typography variant="caption">${producto.precioVenta.toLocaleString()}</Typography>
                </Box>
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Typography variant="caption" color="text.secondary">Ganancia:</Typography>
                    <Typography variant="caption" color="#4caf50" fontWeight="bold">+${producto.ganancia.toLocaleString()}</Typography>
                </Box>
            </CardContent>
        </Card>
    );

    const abrirModalEditar = (producto) => {
        setEditando(producto.id);
        setNombre(producto.nombre);
        setPrecioCosto(producto.precioCosto);
        setPrecioVenta(producto.precioVenta);
        setOpenModal(true);
    };

    const cerrarModal = () => {
        setOpenModal(false);
        setEditando(null);
        setNombre('');
        setPrecioCosto('');
        setPrecioVenta('');
    };

    return (
        <Box sx={{ mt: 2, px: isMobile ? 1 : 2 }}>
            <Paper sx={{ p: isMobile ? 1.5 : 2, mb: 2, backgroundColor: '#e8f5e9' }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 1, mb: 2 }}>
                    <Typography variant="h5" sx={{ display: 'flex', alignItems: 'center', gap: 1, fontSize: isMobile ? '1.2rem' : '1.5rem' }}>
                        <InventoryIcon color="success" /> Mis Productos
                    </Typography>

                    <Button
                        variant="contained"
                        color="success"
                        startIcon={<AddIcon />}
                        onClick={() => setOpenModal(true)}
                        size={isMobile ? "small" : "medium"}
                    >
                        Nuevo
                    </Button>
                </Box>

                <TextField
                    size="small"
                    placeholder="Buscar producto..."
                    value={busqueda}
                    onChange={(e) => setBusqueda(e.target.value)}
                    InputProps={{
                        startAdornment: (
                            <InputAdornment position="start">
                                <SearchIcon fontSize="small" />
                            </InputAdornment>
                        ),
                    }}
                    fullWidth
                />
            </Paper>

            {isMobile ? (
                <Box sx={{ maxHeight: 400, overflow: 'auto' }}>
                    {productosFiltrados.map((prod) => (
                        <TarjetaProducto key={prod.id} producto={prod} />
                    ))}
                    {productosFiltrados.length === 0 && (
                        <Typography textAlign="center" color="text.secondary" py={4}>
                            No hay productos
                        </Typography>
                    )}
                </Box>
            ) : (
                <TableContainer component={Paper}>
                    <Table>
                        <TableHead sx={{ backgroundColor: '#f5f5f5' }}>
                            <TableRow>
                                <TableCell>Producto</TableCell>
                                <TableCell align="right">Precio Costo</TableCell>
                                <TableCell align="right">Precio Venta</TableCell>
                                <TableCell align="right">Ganancia</TableCell>
                                <TableCell align="center">Acciones</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {productosFiltrados.map((prod) => (
                                <TableRow key={prod.id}>
                                    <TableCell>{prod.nombre}</TableCell>
                                    <TableCell align="right">${prod.precioCosto.toLocaleString()}</TableCell>
                                    <TableCell align="right">${prod.precioVenta.toLocaleString()}</TableCell>
                                    <TableCell align="right" sx={{ color: '#4caf50' }}>+${prod.ganancia.toLocaleString()}</TableCell>
                                    <TableCell align="center">
                                        <IconButton size="small" color="primary" onClick={() => abrirModalEditar(prod)}>
                                            <EditIcon />
                                        </IconButton>
                                        <IconButton size="small" color="error" onClick={() => eliminarProducto(prod.id)}>
                                            <DeleteIcon />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </TableContainer>
            )}

            <Modal open={openModal} onClose={cerrarModal} closeAfterTransition>
                <Fade in={openModal}>
                    <Box sx={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                        width: isMobile ? '90%' : 400,
                        bgcolor: 'background.paper',
                        borderRadius: 2,
                        boxShadow: 24,
                        p: 3
                    }}>
                        <Typography variant="h6" mb={2}>
                            {editando ? 'Editar Producto' : 'Nuevo Producto'}
                        </Typography>
                        <TextField
                            fullWidth
                            label="Nombre del producto"
                            value={nombre}
                            onChange={(e) => setNombre(e.target.value)}
                            sx={{ mb: 2 }}
                            size={isMobile ? "small" : "medium"}
                            autoFocus
                        />
                        <TextField
                            fullWidth
                            label="Precio de costo"
                            type="number"
                            value={precioCosto}
                            onChange={(e) => setPrecioCosto(e.target.value)}
                            sx={{ mb: 2 }}
                            size={isMobile ? "small" : "medium"}
                            InputProps={{ startAdornment: <InputAdornment position="start">$</InputAdornment> }}
                        />
                        <TextField
                            fullWidth
                            label="Precio de venta"
                            type="number"
                            value={precioVenta}
                            onChange={(e) => setPrecioVenta(e.target.value)}
                            sx={{ mb: 2 }}
                            size={isMobile ? "small" : "medium"}
                            InputProps={{ startAdornment: <InputAdornment position="start">$</InputAdornment> }}
                        />
                        <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
                            <Button onClick={cerrarModal} size={isMobile ? "small" : "medium"}>Cancelar</Button>
                            <Button variant="contained" onClick={guardarProducto} size={isMobile ? "small" : "medium"}>
                                Guardar
                            </Button>
                        </Box>
                    </Box>
                </Fade>
            </Modal>
        </Box>
    );
};

export default GestorProductos;